window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["aws"]=[{"id":"aws-f0001","card":"q-aws-001-cloud-vs-on-premises","sec":"aws-s002","q":"What is cloud computing vs. on-premises?","a":"<ul>\n  <li><strong>Cloud</strong>: rent resources online, managed by the provider. Flexible and scalable.</li>\n  <li><strong>On-premises</strong>: own and maintain hardware locally. Costly and manual.</li>\n</ul>","hand":false},{"id":"aws-f0002","card":"q-aws-001-cloud-vs-on-premises","sec":"aws-s002","q":"What are the key benefits of AWS over others?","a":"<p>Global reach, 200+ services, pay-as-you-go pricing, strong security and a big ecosystem.</p>","hand":false},{"id":"aws-f0003","card":"q-aws-002-iaas-paas-and-saas","sec":"aws-s003","q":"IaaS vs. PaaS vs. SaaS with AWS examples?","a":"<ul>\n  <li><strong>IaaS</strong>: EC2, S3. You manage the OS and apps.</li>\n  <li><strong>PaaS</strong>: Elastic Beanstalk. You deploy code and AWS handles the rest.</li>\n  <li><strong>SaaS</strong>: WorkMail. You just use it.</li>\n</ul>","hand":false},{"id":"aws-f0004","card":"q-aws-003-elasticity-scalability-and-shared-respon","sec":"aws-s004","q":"What is elasticity in AWS?","a":"<p>Resources auto-scale to match demand. Auto Scaling adds EC2 instances on a traffic spike and removes them when load is low.</p>","hand":false},{"id":"aws-f0005","card":"q-aws-003-elasticity-scalability-and-shared-respon","sec":"aws-s004","q":"Scalability vs. elasticity?","a":"<ul>\n  <li><strong>Scalability</strong>: adding capacity (manual or planned).</li>\n  <li><strong>Elasticity</strong>: automatic, real-time adjustment.</li>\n</ul>","hand":false},{"id":"aws-f0006","card":"q-aws-003-elasticity-scalability-and-shared-respon","sec":"aws-s004","q":"What is the shared responsibility model?","a":"<p>AWS secures the infrastructure (data centers, hardware). You secure your setup (data, IAM, configuration).</p>","hand":false},{"id":"aws-f0007","card":"q-aws-003-elasticity-scalability-and-shared-respon","sec":"aws-s004","q":"How does AWS ensure high availability and fault tolerance?","a":"<p>Multi-AZ and multi-Region design with redundant systems, for example ELB across AZs and RDS failover.</p>","hand":false},{"id":"aws-f0008","card":"q-aws-004-global-infrastructure","sec":"aws-s005","q":"Region, Availability Zone and Edge Location?","a":"<ul>\n  <li><strong>Region</strong>: a geographic area (for example us-east-1).</li>\n  <li><strong>AZ</strong>: an isolated site inside a Region.</li>\n  <li><strong>Edge location</strong>: a CloudFront cache point near users.</li>\n</ul>","hand":false},{"id":"aws-f0009","card":"q-aws-005-pricing-and-the-well-architected-framewo","sec":"aws-s006","q":"How does AWS pricing work and how do you optimize cost?","a":"<p>Pay per use: EC2 by the hour, S3 by the GB. Optimize with Reserved or Spot Instances, right-sizing and Cost Explorer.</p>","hand":false},{"id":"aws-f0010","card":"q-aws-005-pricing-and-the-well-architected-framewo","sec":"aws-s006","q":"What is the AWS Well-Architected Framework and its pillars?","a":"<p>A best-practices guide. Pillars: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization.</p>","hand":false},{"id":"aws-f0011","card":"q-aws-006-ec2-basics","sec":"aws-s007","q":"What is Amazon EC2 and its features?","a":"<p>Virtual servers with flexible instance types, scalable, pay-as-you-go, integrated with S3 and VPC, with Elastic IPs.</p>","hand":false},{"id":"aws-f0012","card":"q-aws-006-ec2-basics","sec":"aws-s007","q":"EC2 instance types: t2.micro vs. m5.large?","a":"<ul>\n  <li><strong>t2.micro</strong>: 1 vCPU, 1 GB, burstable. Good for small tasks.</li>\n  <li><strong>m5.large</strong>: 2 vCPUs, 8 GB, steady performance. Good for web apps.</li>\n</ul>","hand":false},{"id":"aws-f0013","card":"q-aws-006-ec2-basics","sec":"aws-s007","q":"What are AMIs?","a":"<p>Templates (OS plus software) for EC2, stored in S3 and used for consistency and scaling.</p>","hand":false},{"id":"aws-f0014","card":"q-aws-006-ec2-basics","sec":"aws-s007","q":"How do you secure an EC2 instance?","a":"<p>Security Groups, IAM roles, EBS encryption, private subnets, regular updates and monitoring.</p>","hand":false},{"id":"aws-f0015","card":"q-aws-006-ec2-basics","sec":"aws-s007","q":"How do you monitor EC2 performance?","a":"<p>CloudWatch for CPU, memory and I/O metrics plus alarms. Add the SSM Agent and CloudTrail.</p>","hand":false},{"id":"aws-f0016","card":"q-aws-007-auto-scaling","sec":"aws-s008","q":"What is an Auto Scaling Group?","a":"<p>It manages a fleet of EC2 instances, scales on demand and pairs with ELB.</p>","hand":false},{"id":"aws-f0017","card":"q-aws-008-lambda-and-elastic-beanstalk","sec":"aws-s009","q":"What is AWS Lambda and when do you use it?","a":"<p>Serverless compute that runs code on events. Use it over EC2 for short, event-driven tasks such as file processing.</p>","hand":false},{"id":"aws-f0018","card":"q-aws-008-lambda-and-elastic-beanstalk","sec":"aws-s009","q":"Elastic Beanstalk vs. EC2 vs. Lambda?","a":"<ul>\n  <li><strong>Elastic Beanstalk</strong>: PaaS, auto-manages deployment.</li>\n  <li><strong>EC2</strong>: full control, manual.</li>\n  <li><strong>Lambda</strong>: serverless and event-based.</li>\n</ul>","hand":false},{"id":"aws-f0019","card":"q-aws-009-containers","sec":"aws-s010","q":"ECS vs. EKS?","a":"<ul>\n  <li><strong>ECS</strong>: AWS-native container orchestration. Simple.</li>\n  <li><strong>EKS</strong>: managed Kubernetes. Flexible and portable.</li>\n</ul>","hand":false},{"id":"aws-f0020","card":"q-aws-009-containers","sec":"aws-s010","q":"What is AWS Fargate?","a":"<p>Serverless containers for ECS and EKS. There are no EC2 instances to manage; you only define resources.</p>","hand":false},{"id":"aws-f0021","card":"q-aws-010-s3-ebs-and-efs","sec":"aws-s011","q":"S3 vs. EBS vs. EFS?","a":"<ul>\n  <li><strong>S3</strong>: object storage for backups and web content.</li>\n  <li><strong>EBS</strong>: block storage for EC2, for example databases.</li>\n  <li><strong>EFS</strong>: shared file system for multi-instance apps.</li>\n</ul>","hand":false},{"id":"aws-f0022","card":"q-aws-010-s3-ebs-and-efs","sec":"aws-s011","q":"What is Amazon EBS and how does it integrate with EC2?","a":"<p>Block storage that mounts to EC2 as a root or data volume. Snapshots provide backup.</p>","hand":false},{"id":"aws-f0023","card":"q-aws-010-s3-ebs-and-efs","sec":"aws-s011","q":"SSD vs. HDD in EBS?","a":"<ul>\n  <li><strong>SSD (gp3, io2)</strong>: fast and IOPS-heavy. Good for databases.</li>\n  <li><strong>HDD (st1, sc1)</strong>: cheap and throughput-focused. Good for big data and cold storage.</li>\n</ul>","hand":false},{"id":"aws-f0024","card":"q-aws-010-s3-ebs-and-efs","sec":"aws-s011","q":"What is Amazon EFS and when do you choose it over S3?","a":"<p>A shared file system that mounts to multiple EC2 instances. Use it for shared file access, where S3 offers object storage.</p>","hand":false},{"id":"aws-f0025","card":"q-aws-011-s3-features","sec":"aws-s012","q":"What is an S3 bucket and what are its use cases?","a":"<p>An object container used for web hosting, backups, data lakes and content delivery.</p>","hand":false},{"id":"aws-f0026","card":"q-aws-011-s3-features","sec":"aws-s012","q":"What is S3 versioning?","a":"<p>It keeps all versions of an object so older ones can be retrieved. It costs more.</p>","hand":false},{"id":"aws-f0027","card":"q-aws-011-s3-features","sec":"aws-s012","q":"What are the S3 storage classes?","a":"<p>Standard (frequent access), IA (less used), One Zone-IA (cheap, risky), Glacier (archive), Deep Archive (rare access), Intelligent-Tiering (automatic).</p>","hand":false},{"id":"aws-f0028","card":"q-aws-011-s3-features","sec":"aws-s012","q":"How do you secure S3 data?","a":"<p>IAM and bucket policies, SSE-S3 or KMS encryption, versioning, block public access and access logs.</p>","hand":false},{"id":"aws-f0029","card":"q-aws-012-encryption-and-migration","sec":"aws-s013","q":"How do you enable encryption for S3, EBS and EFS?","a":"<ul>\n  <li><strong>S3</strong>: SSE-S3 or KMS through bucket settings.</li>\n  <li><strong>EBS</strong>: KMS at creation.</li>\n  <li><strong>EFS</strong>: KMS at setup.</li>\n</ul>","hand":false},{"id":"aws-f0030","card":"q-aws-012-encryption-and-migration","sec":"aws-s013","q":"How does AWS Snowball help migration?","a":"<p>It is a physical device (80 TB) that ships data to S3 for large, slow transfers.</p>","hand":false},{"id":"aws-f0031","card":"q-aws-013-vpc-subnets-and-route-tables","sec":"aws-s014","q":"What is a VPC and how do you set one up?","a":"<p>A private cloud network. Set a CIDR (for example 10.0.0.0/16), subnets, an Internet Gateway and route tables.</p>","hand":false},{"id":"aws-f0032","card":"q-aws-013-vpc-subnets-and-route-tables","sec":"aws-s014","q":"Public vs. private subnet?","a":"<ul>\n  <li><strong>Public</strong>: routes to the Internet Gateway. Web-facing.</li>\n  <li><strong>Private</strong>: no direct internet. Backend.</li>\n</ul>","hand":false},{"id":"aws-f0033","card":"q-aws-013-vpc-subnets-and-route-tables","sec":"aws-s014","q":"What is a route table in a VPC?","a":"<p>It directs traffic. For example, 0.0.0.0/0 to the Internet Gateway for public subnets.</p>","hand":false},{"id":"aws-f0034","card":"q-aws-014-gateways","sec":"aws-s015","q":"What is a NAT Gateway?","a":"<p>It gives outbound internet access to private subnets. It sits in a public subnet with an Elastic IP.</p>","hand":false},{"id":"aws-f0035","card":"q-aws-014-gateways","sec":"aws-s015","q":"Internet Gateway vs. NAT Gateway?","a":"<ul>\n  <li><strong>Internet Gateway</strong>: two-way public access.</li>\n  <li><strong>NAT</strong>: one-way outbound for private subnets.</li>\n</ul>","hand":false},{"id":"aws-f0036","card":"q-aws-014-gateways","sec":"aws-s015","q":"What is AWS Direct Connect?","a":"<p>A private link to AWS for high-speed, secure hybrid transfers.</p>","hand":false},{"id":"aws-f0037","card":"q-aws-015-load-balancing-dns-and-filtering","sec":"aws-s016","q":"What is an Elastic Load Balancer and what are its types?","a":"<p>It distributes traffic: ALB (HTTP), NLB (TCP/UDP), CLB (legacy).</p>","hand":false},{"id":"aws-f0038","card":"q-aws-015-load-balancing-dns-and-filtering","sec":"aws-s016","q":"What is Amazon Route 53?","a":"<p>A DNS service that resolves domains and offers failover and latency routing.</p>","hand":false},{"id":"aws-f0039","card":"q-aws-015-load-balancing-dns-and-filtering","sec":"aws-s016","q":"Security Group vs. Network ACL?","a":"<ul>\n  <li><strong>Security Group</strong>: stateful, instance-level.</li>\n  <li><strong>NACL</strong>: stateless, subnet-level.</li>\n</ul>","hand":false},{"id":"aws-f0040","card":"q-aws-015-load-balancing-dns-and-filtering","sec":"aws-s016","q":"How do you troubleshoot VPC connectivity?","a":"<p>Check routes, Security Groups, NACLs, Flow Logs and IP assignment.</p>","hand":false},{"id":"aws-f0041","card":"q-aws-016-rds-and-aurora","sec":"aws-s017","q":"What is Amazon RDS and which databases does it support?","a":"<p>Managed relational databases: MySQL, PostgreSQL, MariaDB, Oracle, SQL Server and Aurora.</p>","hand":false},{"id":"aws-f0042","card":"q-aws-016-rds-and-aurora","sec":"aws-s017","q":"What is Multi-AZ in RDS?","a":"<p>Enable Multi-AZ and RDS syncs the primary to a standby in another AZ for failover.</p>","hand":false},{"id":"aws-f0043","card":"q-aws-016-rds-and-aurora","sec":"aws-s017","q":"Aurora vs. RDS?","a":"<ul>\n  <li><strong>Aurora</strong>: faster, scalable, six-copy storage.</li>\n  <li><strong>RDS</strong>: standard engines, simpler.</li>\n</ul>","hand":false},{"id":"aws-f0044","card":"q-aws-017-dynamodb-and-redshift","sec":"aws-s018","q":"What is DynamoDB and when do you use it over RDS?","a":"<p>A NoSQL database that scales fast with low latency. Use it for unstructured, high-traffic data, where RDS is relational.</p>","hand":false},{"id":"aws-f0045","card":"q-aws-017-dynamodb-and-redshift","sec":"aws-s018","q":"How does DynamoDB scale and partition?","a":"<p>On-demand or provisioned scaling. Partitions are derived from the key and split automatically for load.</p>","hand":false},{"id":"aws-f0046","card":"q-aws-017-dynamodb-and-redshift","sec":"aws-s018","q":"What is Amazon Redshift and its use cases?","a":"<p>A data warehouse for analytics and BI on large datasets.</p>","hand":false},{"id":"aws-f0047","card":"q-aws-017-dynamodb-and-redshift","sec":"aws-s018","q":"SQL vs. NoSQL in AWS?","a":"<ul>\n  <li><strong>SQL (RDS)</strong>: structured data, joins.</li>\n  <li><strong>NoSQL (DynamoDB)</strong>: flexible schema, scales.</li>\n</ul>","hand":false},{"id":"aws-f0048","card":"q-aws-018-caching-migration-and-security","sec":"aws-s019","q":"What is Amazon ElastiCache?","a":"<p>An in-memory cache (Redis or Memcached) that speeds up apps by reducing database load.</p>","hand":false},{"id":"aws-f0049","card":"q-aws-018-caching-migration-and-security","sec":"aws-s019","q":"How do you migrate an on-prem database to AWS?","a":"<p>Use DMS: bulk move, then sync changes, then switch the app.</p>","hand":false},{"id":"aws-f0050","card":"q-aws-018-caching-migration-and-security","sec":"aws-s019","q":"How do you secure an AWS database?","a":"<p>IAM, encryption (KMS and SSL), private subnet, logs and backups.</p>","hand":false},{"id":"aws-f0051","card":"q-aws-019-iam","sec":"aws-s020","q":"What is AWS IAM and how do permissions work?","a":"<p>It controls access. Users, roles and policies define the allowed actions.</p>","hand":false},{"id":"aws-f0052","card":"q-aws-019-iam","sec":"aws-s020","q":"IAM policies, roles and users?","a":"<ul>\n  <li><strong>Policies</strong>: JSON rules.</li>\n  <li><strong>Users</strong>: individual identities.</li>\n  <li><strong>Roles</strong>: temporary access for services.</li>\n</ul>","hand":false},{"id":"aws-f0053","card":"q-aws-019-iam","sec":"aws-s020","q":"How do you apply least privilege?","a":"<p>Limit permissions to the essentials with specific policies, and review them with Access Analyzer.</p>","hand":false},{"id":"aws-f0054","card":"q-aws-019-iam","sec":"aws-s020","q":"How does MFA work in AWS?","a":"<p>It adds a second factor. Enable it in IAM and scan the QR code in an authenticator app.</p>","hand":false},{"id":"aws-f0055","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"What is AWS KMS?","a":"<p>It manages encryption keys and encrypts data in S3, RDS and more.</p>","hand":false},{"id":"aws-f0056","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"How do you rotate keys in AWS?","a":"<p>KMS rotates yearly (automatic) or you rotate manually: create a new key and update apps.</p>","hand":false},{"id":"aws-f0057","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"AWS Secrets Manager vs. KMS?","a":"<ul>\n  <li><strong>Secrets Manager</strong>: stores and rotates secrets.</li>\n  <li><strong>KMS</strong>: manages keys.</li>\n</ul>","hand":false},{"id":"aws-f0058","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"What is AWS Shield?","a":"<p>DDoS protection. Standard is free; Advanced is paid and more robust.</p>","hand":false},{"id":"aws-f0059","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"AWS WAF vs. a traditional firewall?","a":"<ul>\n  <li><strong>WAF</strong>: Layer 7 (HTTP) filtering.</li>\n  <li><strong>Traditional</strong>: network-level control.</li>\n</ul>","hand":false},{"id":"aws-f0060","card":"q-aws-020-keys-secrets-and-protection","sec":"aws-s021","q":"How do you audit and monitor security?","a":"<p>CloudTrail (API logs), CloudWatch (alerts) and Config (compliance).</p>","hand":false},{"id":"aws-f0061","card":"q-aws-021-cloudwatch-and-cloudtrail","sec":"aws-s022","q":"What is Amazon CloudWatch?","a":"<p>It monitors metrics and logs for EC2, RDS, Lambda and more.</p>","hand":false},{"id":"aws-f0062","card":"q-aws-021-cloudwatch-and-cloudtrail","sec":"aws-s022","q":"How do you set up a CloudWatch alarm?","a":"<p>Pick a metric (for example CPU), set a threshold and an action (for example SNS).</p>","hand":false},{"id":"aws-f0063","card":"q-aws-021-cloudwatch-and-cloudtrail","sec":"aws-s022","q":"CloudTrail vs. CloudWatch?","a":"<ul>\n  <li><strong>CloudTrail</strong>: API activity logs.</li>\n  <li><strong>CloudWatch</strong>: performance metrics.</li>\n</ul>","hand":false},{"id":"aws-f0064","card":"q-aws-021-cloudwatch-and-cloudtrail","sec":"aws-s022","q":"Metric vs. log in CloudWatch?","a":"<ul>\n  <li><strong>Metric</strong>: numbers (CPU).</li>\n  <li><strong>Log</strong>: text (errors).</li>\n</ul>","hand":false},{"id":"aws-f0065","card":"q-aws-021-cloudwatch-and-cloudtrail","sec":"aws-s022","q":"How do you set up centralized logging?","a":"<p>A CloudWatch Logs group, streamed through the agent, with S3 or Kinesis for scale.</p>","hand":false},{"id":"aws-f0066","card":"q-aws-022-management-tools","sec":"aws-s023","q":"How does AWS Systems Manager help with EC2?","a":"<p>The SSM Agent runs commands, applies patches and opens sessions remotely.</p>","hand":false},{"id":"aws-f0067","card":"q-aws-022-management-tools","sec":"aws-s023","q":"What is AWS Trusted Advisor?","a":"<p>It recommends cost, performance and security fixes.</p>","hand":false},{"id":"aws-f0068","card":"q-aws-022-management-tools","sec":"aws-s023","q":"What is AWS Config?","a":"<p>It tracks resource configurations and flags compliance drift.</p>","hand":false},{"id":"aws-f0069","card":"q-aws-022-management-tools","sec":"aws-s023","q":"How do you automate with the AWS CLI and SDKs?","a":"<p>Script the tasks, for example <code>aws ec2 start-instances</code>, or Boto3 code.</p>","hand":false},{"id":"aws-f0070","card":"q-aws-022-management-tools","sec":"aws-s023","q":"How do you troubleshoot a failed deployment?","a":"<p>Check CloudWatch logs and CloudTrail, then roll back with the deployment tool.</p>","hand":false},{"id":"aws-f0071","card":"q-aws-023-availability-and-scaling","sec":"aws-s024","q":"How do you build a highly available app on AWS?","a":"<p>Multi-AZ ELB, Auto Scaling, RDS Multi-AZ and Route 53.</p>","hand":false},{"id":"aws-f0072","card":"q-aws-023-availability-and-scaling","sec":"aws-s024","q":"Horizontal vs. vertical scaling?","a":"<ul>\n  <li><strong>Horizontal</strong>: more instances.</li>\n  <li><strong>Vertical</strong>: a bigger instance.</li>\n</ul>","hand":false},{"id":"aws-f0073","card":"q-aws-023-availability-and-scaling","sec":"aws-s024","q":"Stateless vs. stateful apps?","a":"<ul>\n  <li><strong>Stateless</strong>: no stored memory (Lambda).</li>\n  <li><strong>Stateful</strong>: retains data (RDS).</li>\n</ul>","hand":false},{"id":"aws-f0074","card":"q-aws-023-availability-and-scaling","sec":"aws-s024","q":"What is AWS Global Accelerator?","a":"<p>It routes users to the nearest edge for low latency and failover.</p>","hand":false},{"id":"aws-f0075","card":"q-aws-024-cost-and-anti-patterns","sec":"aws-s025","q":"What does a cost-effective architecture look like?","a":"<p>Right-size, use Reserved or Spot capacity, go serverless and tier storage.</p>","hand":false},{"id":"aws-f0076","card":"q-aws-024-cost-and-anti-patterns","sec":"aws-s025","q":"What are common AWS architecture anti-patterns?","a":"<p>Overprovisioning, no elasticity, weak security and no IaC.</p>","hand":false},{"id":"aws-f0077","card":"q-aws-025-microservices-serverless-migration-and-d","sec":"aws-s026","q":"How do you run microservices on AWS?","a":"<p>ECS or EKS, Lambda, API Gateway and SQS. Scalable and independent.</p>","hand":false},{"id":"aws-f0078","card":"q-aws-025-microservices-serverless-migration-and-d","sec":"aws-s026","q":"What is a serverless architecture on AWS?","a":"<p>Lambda, API Gateway, DynamoDB, S3 and Step Functions.</p>","hand":false},{"id":"aws-f0079","card":"q-aws-025-microservices-serverless-migration-and-d","sec":"aws-s026","q":"How do you migrate a monolith to AWS?","a":"<p>Lift-and-shift to EC2, then refactor into microservices (ECS, Lambda).</p>","hand":false},{"id":"aws-f0080","card":"q-aws-025-microservices-serverless-migration-and-d","sec":"aws-s026","q":"What is the disaster recovery approach in AWS?","a":"<p>Multi-region deployment, S3 replication, RDS replicas and Route 53 failover.</p>","hand":false},{"id":"aws-f0081","card":"q-aws-026-code-services","sec":"aws-s027","q":"What is AWS CodePipeline?","a":"<p>A CI/CD service that integrates CodeCommit, CodeBuild and CodeDeploy.</p>","hand":false},{"id":"aws-f0082","card":"q-aws-026-code-services","sec":"aws-s027","q":"How do you build CI/CD with CodeBuild and CodeDeploy?","a":"<p>Pipeline stages: Source (CodeCommit), Build (CodeBuild), Deploy (CodeDeploy).</p>","hand":false},{"id":"aws-f0083","card":"q-aws-026-code-services","sec":"aws-s027","q":"What is AWS CodeStar?","a":"<p>It unifies pipeline setup: CodeCommit, CodeBuild and hosting.</p>","hand":false},{"id":"aws-f0084","card":"q-aws-027-deployment-and-rollback","sec":"aws-s028","q":"Blue/green vs. rolling deployment?","a":"<ul>\n  <li><strong>Blue/green</strong>: full switch, no downtime.</li>\n  <li><strong>Rolling</strong>: gradual, partial risk.</li>\n</ul>","hand":false},{"id":"aws-f0085","card":"q-aws-027-deployment-and-rollback","sec":"aws-s028","q":"How do you roll back a failed deployment?","a":"<ul>\n  <li><strong>CodeDeploy</strong>: switch back (blue/green).</li>\n  <li><strong>CloudFormation</strong>: revert the stack.</li>\n</ul>","hand":false},{"id":"aws-f0086","card":"q-aws-028-iac-and-containers","sec":"aws-s029","q":"How is CloudFormation used for IaC?","a":"<p>Templates define resources. It provisions, updates and rolls back.</p>","hand":false},{"id":"aws-f0087","card":"q-aws-028-iac-and-containers","sec":"aws-s029","q":"What are the benefits of AWS OpsWorks?","a":"<p>Managed Chef or Puppet that automates deployment and scaling.</p>","hand":false},{"id":"aws-f0088","card":"q-aws-028-iac-and-containers","sec":"aws-s029","q":"How do Docker and ECS work together on AWS?","a":"<p>Containers package apps, ECS runs them and scales them from ECR images.</p>","hand":false},{"id":"aws-f0089","card":"q-aws-028-iac-and-containers","sec":"aws-s029","q":"How do you automate infrastructure provisioning?","a":"<p>CloudFormation or Terraform, CLI scripts and Auto Scaling.</p>","hand":false},{"id":"aws-f0090","card":"q-aws-028-iac-and-containers","sec":"aws-s029","q":"How do you handle secrets in CI/CD?","a":"<p>Secrets Manager, IAM roles and KMS encryption.</p>","hand":false},{"id":"aws-f0091","card":"q-aws-029-migration-and-scale","sec":"aws-s030","q":"How do you migrate a 10 TB database with minimal downtime?","a":"<p>Snowball for the bulk, DMS for sync, then switch in a maintenance window.</p>","hand":false},{"id":"aws-f0092","card":"q-aws-029-migration-and-scale","sec":"aws-s030","q":"Design a web app for 1M users daily.","a":"<p>ELB, Auto Scaling EC2, RDS Multi-AZ, ElastiCache and S3 with CloudFront.</p>","hand":false},{"id":"aws-f0093","card":"q-aws-029-migration-and-scale","sec":"aws-s030","q":"How do you handle a traffic spike?","a":"<p>Auto Scaling, RDS replicas, CloudFront and Lambda.</p>","hand":false},{"id":"aws-f0094","card":"q-aws-030-troubleshooting-and-security","sec":"aws-s031","q":"How do you troubleshoot an unreachable EC2 instance?","a":"<p>Check status, Security Groups, routes, IP and logs. Restart if needed.</p>","hand":false},{"id":"aws-f0095","card":"q-aws-030-troubleshooting-and-security","sec":"aws-s031","q":"How do you fix slow application performance?","a":"<p>Use CloudWatch and X-Ray, then scale EC2, add caching and optimize the database.</p>","hand":false},{"id":"aws-f0096","card":"q-aws-030-troubleshooting-and-security","sec":"aws-s031","q":"How do you secure an S3 plus RDS app?","a":"<p>IAM, encryption, private subnets and restricted access.</p>","hand":false},{"id":"aws-f0097","card":"q-aws-030-troubleshooting-and-security","sec":"aws-s031","q":"An S3 bucket was made public. What do you do?","a":"<p>Remove public access, turn on the block-public-access settings and audit with CloudTrail.</p>","hand":false},{"id":"aws-f0098","card":"q-aws-031-resilience-and-cost","sec":"aws-s032","q":"What is a backup and recovery strategy?","a":"<p>EBS snapshots, RDS backups, S3 versioning and Glacier.</p>","hand":false},{"id":"aws-f0099","card":"q-aws-031-resilience-and-cost","sec":"aws-s032","q":"How do you reduce costs from overprovisioning?","a":"<p>Cost Explorer, right-sizing, Spot, stopping idle resources and tiering S3.</p>","hand":false},{"id":"aws-f0100","card":"q-aws-031-resilience-and-cost","sec":"aws-s032","q":"How do you design multi-region DR?","a":"<p>Route 53 failover, S3 replication, RDS replicas and AMIs.</p>","hand":false},{"id":"aws-f0101","card":"q-aws-032-ownership-and-deep-dives","sec":"aws-s033","q":"Tell me about a time you took ownership of a project.","a":"<p>Led an app migration: planned it, executed it and beat the deadline.</p>","hand":false},{"id":"aws-f0102","card":"q-aws-032-ownership-and-deep-dives","sec":"aws-s033","q":"Tell me about a time you dove deep into a problem.","a":"<p>Fixed crashes by tracing a CPU spike and optimizing a query.</p>","hand":false},{"id":"aws-f0103","card":"q-aws-033-disagreement-speed-and-customers","sec":"aws-s034","q":"How did you handle a disagreement?","a":"<p>Debated EC2 vs. Lambda, committed to the decision, optimized it and the team aligned later.</p>","hand":false},{"id":"aws-f0104","card":"q-aws-033-disagreement-speed-and-customers","sec":"aws-s034","q":"Tell me about delivering a fast solution.","a":"<p>Built a dashboard in 5 days instead of 2 weeks using Glue, Athena and QuickSight.</p>","hand":false},{"id":"aws-f0105","card":"q-aws-033-disagreement-speed-and-customers","sec":"aws-s034","q":"How did you ensure customer satisfaction?","a":"<p>Migrated an app with zero downtime and cost savings, with constant updates to the customer.</p>","hand":false},{"id":"aws-f0106","card":"q-aws-034-create-an-ec2-instance","sec":"aws-s035","q":"How do you create an EC2 instance with the AWS CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 run-instances \\\n    --image-id ami-0c55b159cbfafe1f0 \\\n    --instance-type t2.micro \\\n    --key-name my-key-pair \\\n    --security-group-ids sg-12345678 \\\n    --subnet-id subnet-12345678 \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0107","card":"q-aws-035-create-an-rds-instance-and-a-read-replic","sec":"aws-s036","q":"How do you create an RDS instance with the AWS CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws rds create-db-instance \\\n    --db-instance-identifier my-rds-instance \\\n    --db-instance-class db.t3.micro \\\n    --engine mysql \\\n    --master-username admin \\\n    --master-user-password &lt;master-password&gt; \\\n    --allocated-storage 20 \\\n    --vpc-security-group-ids sg-12345678 \\\n    --db-subnet-group-name my-subnet-group \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0108","card":"q-aws-035-create-an-rds-instance-and-a-read-replic","sec":"aws-s036","q":"How do you create an RDS read replica for an existing instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws rds create-db-instance-read-replica \\\n    --db-instance-identifier my-rds-replica \\\n    --source-db-instance-identifier my-rds-instance \\\n    --db-instance-class db.t3.micro \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0109","card":"q-aws-035-create-an-rds-instance-and-a-read-replic","sec":"aws-s036","q":"How do you attach a security group to an RDS instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws rds modify-db-instance \\\n    --db-instance-identifier my-rds-instance \\\n    --vpc-security-group-ids sg-12345678 \\\n    --apply-immediately \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0110","card":"q-aws-036-create-an-s3-bucket","sec":"aws-s037","q":"How do you create an S3 bucket with the AWS CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3api create-bucket \\\n    --bucket my-unique-bucket-name \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0111","card":"q-aws-037-create-an-iam-role-and-attach-it-to-an-e","sec":"aws-s038","q":"How do you create an IAM role and attach it to an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create IAM role\naws iam create-role \\\n    --role-name ec2-role \\\n    --assume-role-policy-document &#x27;{&quot;Version&quot;:&quot;2012-10-17&quot;,&quot;Statement&quot;:[{&quot;Effect&quot;:&quot;Allow&quot;,&quot;Principal&quot;:{&quot;Service&quot;:&quot;ec2.amazonaws.com&quot;},&quot;Action&quot;:&quot;sts:AssumeRole&quot;}]}&#x27;\n# Attach policy to role\naws iam attach-role-policy \\\n    --role-name ec2-role \\\n    --policy-arn arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess\n# Create instance profile\naws iam create-instance-profile \\\n    --instance-profile-name ec2-instance-profile\n# Add role to instance profile\naws iam add-role-to-instance-profile \\\n    --instance-profile-name ec2-instance-profile \\\n    --role-name ec2-role\n# Attach to EC2 instance\naws ec2 associate-iam-instance-profile \\\n    --instance-id i-1234567890abcdef0 \\\n    --iam-instance-profile Name=ec2-instance-profile</code></pre></div>","hand":false},{"id":"aws-f0112","card":"q-aws-038-create-and-attach-an-ebs-volume","sec":"aws-s039","q":"How do you create an EBS volume and attach it to an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create EBS volume\naws ec2 create-volume \\\n    --availability-zone us-east-1a \\\n    --size 10 \\\n    --volume-type gp3 \\\n    --region us-east-1\n# Attach volume to EC2 instance\naws ec2 attach-volume \\\n    --volume-id vol-1234567890abcdef0 \\\n    --instance-id i-1234567890abcdef0 \\\n    --device /dev/xvdf \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0113","card":"q-aws-039-create-a-vpc-with-a-public-subnet","sec":"aws-s040","q":"How do you create a VPC with a public subnet using the AWS CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create VPC\naws ec2 create-vpc \\\n    --cidr-block 10.0.0.0/16 \\\n    --region us-east-1\n# Create subnet\naws ec2 create-subnet \\\n    --vpc-id vpc-12345678 \\\n    --cidr-block 10.0.1.0/24 \\\n    --availability-zone us-east-1a \\\n    --region us-east-1\n# Create internet gateway\naws ec2 create-internet-gateway \\\n    --region us-east-1\n# Attach internet gateway to VPC\naws ec2 attach-internet-gateway \\\n    --internet-gateway-id igw-12345678 \\\n    --vpc-id vpc-12345678 \\\n    --region us-east-1\n# Create route table\naws ec2 create-route-table \\\n    --vpc-id vpc-12345678 \\\n    --region us-east-1\n# Add route to internet gateway\naws ec2 create-route \\\n    --route-table-id rtb-12345678 \\\n    --destination-cidr-block 0.0.0.0/0 \\\n    --gateway-id igw-12345678 \\\n    --region us-east-1\n# Associate route table with subnet\naws ec2 associate-route-table \\\n    --route-table-id rtb-12345678 \\\n    --subnet-id subnet-12345678 \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0114","card":"q-aws-040-create-and-attach-a-security-group","sec":"aws-s041","q":"How do you create a security group and attach it to an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create security group\naws ec2 create-security-group \\\n    --group-name my-security-group \\\n    --description &quot;My security group&quot; \\\n    --vpc-id vpc-12345678 \\\n    --region us-east-1\n# Add inbound rule\naws ec2 authorize-security-group-ingress \\\n    --group-id sg-12345678 \\\n    --protocol tcp \\\n    --port 22 \\\n    --cidr 0.0.0.0/0 \\\n    --region us-east-1\n# Attach to EC2 instance\naws ec2 modify-instance-attribute \\\n    --instance-id i-1234567890abcdef0 \\\n    --groups sg-12345678 \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0115","card":"q-aws-041-create-an-sns-topic-and-an-email-subscri","sec":"aws-s042","q":"How do you create an SNS topic and subscribe an email endpoint?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create SNS topic\naws sns create-topic \\\n    --name my-topic \\\n    --region us-east-1\n# Subscribe email endpoint\naws sns subscribe \\\n    --topic-arn arn:aws:sns:us-east-1:123456789012:my-topic \\\n    --protocol email \\\n    --notification-endpoint user@example.com \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0116","card":"q-aws-042-attach-an-elastic-ip","sec":"aws-s043","q":"How do you attach an Elastic IP to an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Allocate Elastic IP\naws ec2 allocate-address \\\n    --domain vpc \\\n    --region us-east-1\n# Associate Elastic IP with instance\naws ec2 associate-address \\\n    --instance-id i-1234567890abcdef0 \\\n    --allocation-id eipalloc-12345678 \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0117","card":"q-aws-043-create-an-ecs-cluster-and-run-a-fargate","sec":"aws-s044","q":"How do you create an ECS cluster and deploy a task definition?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create ECS cluster\naws ecs create-cluster \\\n    --cluster-name my-ecs-cluster \\\n    --region us-east-1\n# Register task definition\naws ecs register-task-definition \\\n    --family my-task \\\n    --network-mode awsvpc \\\n    --requires-compatibilities FARGATE \\\n    --cpu &quot;256&quot; \\\n    --memory &quot;512&quot; \\\n    --execution-role-arn arn:aws:iam::123456789012:role/ecs-task-execution-role \\\n    --container-definitions &#x27;[{&quot;name&quot;:&quot;my-container&quot;,&quot;image&quot;:&quot;amazon/amazon-ecs-sample&quot;,&quot;essential&quot;:true,&quot;portMappings&quot;:[{&quot;containerPort&quot;:80,&quot;hostPort&quot;:80}]}]&#x27; \\\n    --region us-east-1\n# Run task\naws ecs run-task \\\n    --cluster my-ecs-cluster \\\n    --task-definition my-task \\\n    --launch-type FARGATE \\\n    --network-configuration &quot;awsvpcConfiguration={subnets=[subnet-12345678],securityGroups=[sg-12345678],assignPublicIp=ENABLED}&quot; \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0118","card":"q-aws-044-launch-template-and-auto-scaling-group","sec":"aws-s045","q":"How do you create an Auto Scaling group from an EC2 launch template?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># Create launch template\naws ec2 create-launch-template \\\n    --launch-template-name my-launch-template \\\n    --version-description &quot;v1&quot; \\\n    --launch-template-data &#x27;{&quot;ImageId&quot;:&quot;ami-0c55b159cbfafe1f0&quot;,&quot;InstanceType&quot;:&quot;t2.micro&quot;,&quot;KeyName&quot;:&quot;my-key-pair&quot;,&quot;SecurityGroupIds&quot;:[&quot;sg-12345678&quot;]}&#x27; \\\n    --region us-east-1\n# Create Auto Scaling group\naws autoscaling create-auto-scaling-group \\\n    --auto-scaling-group-name my-asg \\\n    --launch-template LaunchTemplateName=my-launch-template,Version=1 \\\n    --min-size 1 \\\n    --max-size 3 \\\n    --desired-capacity 2 \\\n    --vpc-zone-identifier subnet-12345678,subnet-87654321 \\\n    --region us-east-1</code></pre></div>","hand":false},{"id":"aws-f0119","card":"q-aws-045-lambda-function","sec":"aws-s046","q":"How do you create a Lambda function with CloudFormation (YAML)?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Resources:\n    MyLambdaFunction:\n        Type: AWS::Lambda::Function\n        Properties:\n            FunctionName: my-lambda-function\n            Handler: index.handler\n            Runtime: nodejs18.x\n            Role: arn:aws:iam::123456789012:role/lambda-exec-role\n            Code:\n                S3Bucket: my-code-bucket\n                S3Key: lambda-code.zip</code></pre></div>","hand":false},{"id":"aws-f0120","card":"q-aws-046-cloudwatch-alarm-for-ec2","sec":"aws-s047","q":"How do you create a CloudWatch alarm for an EC2 instance with CloudFormation?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Resources:\n    MyCloudWatchAlarm:\n        Type: AWS::CloudWatch::Alarm\n        Properties:\n            AlarmName: ec2-cpu-alarm\n            MetricName: CPUUtilization\n            Namespace: AWS/EC2\n            Statistic: Average\n            Period: 300\n            EvaluationPeriods: 2\n            Threshold: 80\n            ComparisonOperator: GreaterThanThreshold\n            Dimensions:\n                - Name: InstanceId\n                    Value: i-1234567890abcdef0\n            AlarmActions:\n                - arn:aws:sns:us-east-1:123456789012:my-topic</code></pre></div>","hand":false},{"id":"aws-f0121","card":"q-aws-047-api-gateway-in-front-of-lambda","sec":"aws-s048","q":"How do you create an API Gateway and attach it to a Lambda function with CloudFormation?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Resources:\n    MyApiGateway:\n        Type: AWS::ApiGateway::RestApi\n        Properties:\n            Name: my-api\n    MyResource:\n        Type: AWS::ApiGateway::Resource\n        Properties:\n            RestApiId: !Ref MyApiGateway\n            ParentId: !GetAtt MyApiGateway.RootResourceId\n            PathPart: &quot;hello&quot;\n    MyMethod:\n        Type: AWS::ApiGateway::Method\n        Properties:\n            RestApiId: !Ref MyApiGateway\n            ResourceId: !Ref MyResource\n            HttpMethod: GET\n            AuthorizationType: NONE\n            Integration:\n                Type: AWS\n                IntegrationHttpMethod: POST\n                Uri: !Sub arn:aws:apigateway:us-east-1:lambda:path/2015-03-31/functions/${MyLambdaFunction.Arn}/invocations\n    MyLambdaFunction:\n        Type: AWS::Lambda::Function\n        Properties:\n            FunctionName: my-lambda-function\n            Handler: index.handler\n            Runtime: nodejs18.x\n            Role: arn:aws:iam::123456789012:role/lambda-exec-role\n            Code:\n                S3Bucket: my-code-bucket\n                S3Key: lambda-code.zip\n    LambdaPermission:\n        Type: AWS::Lambda::Permission\n        Properties:\n            Action: lambda:InvokeFunction\n            FunctionName: !Ref MyLambdaFunction\n            Principal: apigateway.amazonaws.com\n            SourceArn: !Sub arn:aws:execute-api:us-east-1:123456789012:${MyApiGateway}/*/*/*</code></pre></div>\n<p>The <code>AWS::Lambda::Permission</code> resource lets API Gateway invoke the function.</p>","hand":false},{"id":"aws-f0122","card":"q-aws-048-step-functions-state-machine","sec":"aws-s049","q":"How do you create a Step Functions state machine with CloudFormation?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Resources:\n    MyStateMachine:\n        Type: AWS::StepFunctions::StateMachine\n        Properties:\n            StateMachineName: my-state-machine\n            RoleArn: arn:aws:iam::123456789012:role/step-functions-role\n            DefinitionString: |\n                {\n                    &quot;StartAt&quot;: &quot;Hello&quot;,\n                    &quot;States&quot;: {\n                        &quot;Hello&quot;: {\n                            &quot;Type&quot;: &quot;Pass&quot;,\n                            &quot;Result&quot;: &quot;Hello World&quot;,\n                            &quot;End&quot;: true\n                        }\n                    }\n                }</code></pre></div>","hand":false},{"id":"aws-f0123","card":"q-aws-049-launch-template-with-the-cloudwatch-agen","sec":"aws-s050","q":"How do you set up an Auto Scaling group that scales on CPU and memory utilization?","a":"<p>Step 1: create a launch template whose user data installs the CloudWatch agent.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 create-launch-template \\\n  --launch-template-name MyWebServerTemplate \\\n  --version-description &quot;v1&quot; \\\n  --launch-template-data &#x27;{\n    &quot;ImageId&quot;: &quot;&lt;ami-id&gt;&quot;,\n    &quot;InstanceType&quot;: &quot;t2.micro&quot;,\n    &quot;KeyName&quot;: &quot;&lt;key-pair-name&gt;&quot;,\n    &quot;NetworkInterfaces&quot;: [{&quot;AssociatePublicIpAddress&quot;: true, &quot;DeviceIndex&quot;: 0, &quot;SubnetId&quot;: &quot;&lt;subnet-id&gt;&quot;, &quot;Groups&quot;: [&quot;&lt;security-group-id&gt;&quot;]}],\n    &quot;UserData&quot;: &quot;&#x27;$(echo -e &quot;#!/bin/bash\\nyum install -y amazon-cloudwatch-agent\\n/opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-config-wizard&quot; | base64)&#x27;&quot;\n  }&#x27;</code></pre></div>\n<p>Step 2: create the Auto Scaling group.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws autoscaling create-auto-scaling-group \\\n  --auto-scaling-group-name MyWebServerASG \\\n  --launch-template &quot;LaunchTemplateName=MyWebServerTemplate,Version=1&quot; \\\n  --min-size 1 \\\n  --max-size 4 \\\n  --desired-capacity 2 \\\n  --vpc-zone-identifier &quot;&lt;subnet-id-1&gt;,&lt;subnet-id-2&gt;&quot;</code></pre></div>","hand":false},{"id":"aws-f0124","card":"q-aws-050-step-scaling-policy","sec":"aws-s051","q":"How do you define an EC2 Auto Scaling step scaling policy that adds one instance with a 300 second cooldown?","a":"<p>Save the policy to <code>step-scaling-policy.json</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;AdjustmentType&quot;: &quot;ChangeInCapacity&quot;,\n  &quot;StepAdjustments&quot;: [{&quot;MetricIntervalLowerBound&quot;: 0, &quot;ScalingAdjustment&quot;: 1}],\n  &quot;Cooldown&quot;: 300\n}</code></pre></div>","hand":true},{"id":"aws-f0125","card":"q-aws-050-step-scaling-policy","sec":"aws-s051","q":"Which AWS CLI command creates a step scaling policy from <code>step-scaling-policy.json</code>, and what do you note from its output?","a":"<p><code>aws autoscaling put-scaling-policy</code> with <code>--policy-type StepScaling</code>. Note the <code>PolicyARN</code> from the output, because the alarms need it.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws autoscaling put-scaling-policy \\\n  --auto-scaling-group-name MyWebServerASG \\\n  --policy-name MyStepScalingPolicy \\\n  --policy-type StepScaling \\\n  --step-scaling-policy-configuration file://step-scaling-policy.json</code></pre></div>","hand":true},{"id":"aws-f0126","card":"q-aws-051-cpu-and-memory-alarms","sec":"aws-s052","q":"How do you create a CloudWatch alarm that scales an Auto Scaling group out when average CPU is higher than 50%?","a":"<p>Use <code>aws cloudwatch put-metric-alarm</code> on <code>CPUUtilization</code> in <code>AWS/EC2</code>, with threshold 50, and put the scaling policy ARN in <code>--alarm-actions</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch put-metric-alarm \\\n  --alarm-name HighCPUAlarm \\\n  --metric-name CPUUtilization \\\n  --namespace AWS/EC2 \\\n  --statistic Average \\\n  --period 300 \\\n  --evaluation-periods 2 \\\n  --threshold 50 \\\n  --comparison-operator GreaterThanThreshold \\\n  --dimensions Name=AutoScalingGroupName,Value=MyWebServerASG \\\n  --alarm-actions &lt;scaling-policy-arn&gt;</code></pre></div>","hand":true},{"id":"aws-f0127","card":"q-aws-051-cpu-and-memory-alarms","sec":"aws-s052","q":"How do you create a CloudWatch alarm on memory at 70% for an Auto Scaling group, and what does it need?","a":"<p>The CloudWatch agent must push memory metrics under namespace <code>CWAgent</code>. The alarm uses <code>MemoryUtilization</code> in that namespace with threshold 70.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch put-metric-alarm \\\n  --alarm-name HighMemoryAlarm \\\n  --metric-name MemoryUtilization \\\n  --namespace CWAgent \\\n  --statistic Average \\\n  --period 300 \\\n  --evaluation-periods 2 \\\n  --threshold 70 \\\n  --comparison-operator GreaterThanThreshold \\\n  --dimensions Name=AutoScalingGroupName,Value=MyWebServerASG \\\n  --alarm-actions &lt;scaling-policy-arn&gt;</code></pre></div>","hand":true},{"id":"aws-f0128","card":"q-aws-051-cpu-and-memory-alarms","sec":"aws-s052","q":"What do <code>--period 300</code> and <code>--evaluation-periods 2</code> mean in the CPU alarm for Auto Scaling?","a":"<p>The alarm uses a 300 second period and 2 evaluation periods, with the <code>Average</code> statistic.</p>","hand":true},{"id":"aws-f0129","card":"q-aws-052-verify-the-setup","sec":"aws-s053","q":"Which AWS CLI commands verify an Auto Scaling group and its CloudWatch alarms?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws autoscaling describe-auto-scaling-groups --auto-scaling-group-names MyWebServerASG\naws cloudwatch describe-alarms --alarm-names HighCPUAlarm HighMemoryAlarm</code></pre></div>","hand":true},{"id":"aws-f0130","card":"q-aws-052-verify-the-setup","sec":"aws-s053","q":"Which placeholders must you replace in the Auto Scaling CLI setup?","a":"<p><code>&lt;ami-id&gt;</code>, <code>&lt;key-pair-name&gt;</code>, <code>&lt;subnet-id&gt;</code>, <code>&lt;security-group-id&gt;</code> and <code>&lt;scaling-policy-arn&gt;</code>, with real values.</p>","hand":true},{"id":"aws-f0131","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you find EC2 instances in a specific VPC?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 describe-instances --filters &quot;Name=vpc-id,Values=vpc-12345678&quot; --query &quot;Reservations[].Instances[].InstanceId&quot; --output text</code></pre></div>","hand":false},{"id":"aws-f0132","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you stop all running EC2 instances in a region?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 stop-instances --instance-ids $(aws ec2 describe-instances --region us-east-1 --filters &quot;Name=instance-state-name,Values=running&quot; --query &quot;Reservations[].Instances[].InstanceId&quot; --output text)</code></pre></div>","hand":false},{"id":"aws-f0133","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you tag untagged EC2 instances?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 describe-instances --query &#x27;Reservations[*].Instances[?not_null(Tags)==`false`].[InstanceId]&#x27; --output text | xargs -I {} aws ec2 create-tags --resources {} --tags Key=Environment,Value=Dev</code></pre></div>","hand":false},{"id":"aws-f0134","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you enable termination protection on EC2?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 modify-instance-attribute --instance-id &lt;instance-id&gt; --disable-api-termination</code></pre></div>","hand":false},{"id":"aws-f0135","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you check the IAM role on an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 describe-instances --instance-ids &lt;instance-id&gt; --query &#x27;Reservations[0].Instances[0].IamInstanceProfile&#x27;</code></pre></div>","hand":false},{"id":"aws-f0136","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you create a security group and allow port 80?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 create-security-group --group-name MySG --description &quot;Allow HTTP&quot; --vpc-id vpc-12345678\naws ec2 authorize-security-group-ingress --group-name MySG --protocol tcp --port 80 --cidr 0.0.0.0/0</code></pre></div>","hand":false},{"id":"aws-f0137","card":"q-aws-053-ec2-commands","sec":"aws-s054","q":"How do you update an EC2 security group to allow HTTPS?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 authorize-security-group-ingress --group-id &lt;security-group-id&gt; --protocol tcp --port 443 --cidr 0.0.0.0/0</code></pre></div>","hand":false},{"id":"aws-f0138","card":"q-aws-054-ebs-and-ami-commands","sec":"aws-s055","q":"How do you attach an EBS volume to an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 attach-volume --volume-id vol-12345678 --instance-id i-12345678 --device /dev/xvdf</code></pre></div>","hand":false},{"id":"aws-f0139","card":"q-aws-054-ebs-and-ami-commands","sec":"aws-s055","q":"How do you create a snapshot of an EBS volume?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 create-snapshot --volume-id &lt;volume-id&gt; --description &quot;Snapshot&quot;</code></pre></div>","hand":false},{"id":"aws-f0140","card":"q-aws-054-ebs-and-ami-commands","sec":"aws-s055","q":"How do you increase an EBS volume size?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 modify-volume --volume-id &lt;volume-id&gt; --size 100</code></pre></div>","hand":false},{"id":"aws-f0141","card":"q-aws-054-ebs-and-ami-commands","sec":"aws-s055","q":"How do you deregister an AMI and delete its snapshots?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ec2 deregister-image --image-id &lt;ami-id&gt;\naws ec2 describe-snapshots --filters Name=description,Values=&quot;Created by*for &lt;ami-id&gt;*&quot; --query &#x27;Snapshots[*].SnapshotId&#x27; --output text | xargs -n1 aws ec2 delete-snapshot --snapshot-id</code></pre></div>","hand":false},{"id":"aws-f0142","card":"q-aws-055-s3-commands","sec":"aws-s056","q":"How do you check an S3 bucket's size?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3api list-objects-v2 --bucket my-bucket --query &quot;[sum(Contents[].Size)]&quot; --output text</code></pre></div>","hand":false},{"id":"aws-f0143","card":"q-aws-055-s3-commands","sec":"aws-s056","q":"How do you delete all objects in an S3 bucket?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3 rm s3://my-bucket --recursive</code></pre></div>","hand":false},{"id":"aws-f0144","card":"q-aws-055-s3-commands","sec":"aws-s056","q":"How do you list S3 buckets with versioning disabled?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3api list-buckets --query &#x27;Buckets[].Name&#x27; --output text | xargs -I {} sh -c &#x27;aws s3api get-bucket-versioning --bucket {} | grep -q &quot;Enabled&quot; || echo {}&#x27;</code></pre></div>","hand":false},{"id":"aws-f0145","card":"q-aws-055-s3-commands","sec":"aws-s056","q":"How do you copy a file between S3 buckets in different regions?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3 cp s3://source-bucket/file.txt s3://destination-bucket/file.txt --source-region us-east-1 --region us-west-2</code></pre></div>","hand":false},{"id":"aws-f0146","card":"q-aws-055-s3-commands","sec":"aws-s056","q":"How do you enable encryption on an S3 bucket?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws s3api put-bucket-encryption --bucket &lt;bucket-name&gt; --server-side-encryption-configuration &#x27;{&quot;Rules&quot;:[{&quot;ApplyServerSideEncryptionByDefault&quot;:{&quot;SSEAlgorithm&quot;:&quot;AES256&quot;}}]}&#x27;</code></pre></div>","hand":false},{"id":"aws-f0147","card":"q-aws-056-iam-cloudtrail-and-cloudwatch-commands","sec":"aws-s057","q":"How do you list IAM users created in the last 30 days?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws iam list-users --query &quot;Users[?CreateDate&gt;=`2025-03-08`].UserName&quot; --output text</code></pre></div>","hand":false},{"id":"aws-f0148","card":"q-aws-056-iam-cloudtrail-and-cloudwatch-commands","sec":"aws-s057","q":"How do you rotate an IAM access key for a user?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws iam create-access-key --user-name &lt;username&gt;\naws iam delete-access-key --user-name &lt;username&gt; --access-key-id &lt;old-key-id&gt;</code></pre></div>","hand":false},{"id":"aws-f0149","card":"q-aws-056-iam-cloudtrail-and-cloudwatch-commands","sec":"aws-s057","q":"How do you check CloudTrail events for an EC2 instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudtrail lookup-events --lookup-attributes AttributeKey=ResourceName,AttributeValue=&lt;instance-id&gt; --query &#x27;Events[*].{Time:EventTime,Event:EventName,User:Username}&#x27; --output table</code></pre></div>","hand":false},{"id":"aws-f0150","card":"q-aws-056-iam-cloudtrail-and-cloudwatch-commands","sec":"aws-s057","q":"How do you list CloudWatch alarms in the ALARM state?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch describe-alarms --state-value ALARM</code></pre></div>","hand":false},{"id":"aws-f0151","card":"q-aws-056-iam-cloudtrail-and-cloudwatch-commands","sec":"aws-s057","q":"How do you troubleshoot a CloudWatch alarm?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch describe-alarms --alarm-names &lt;alarm-name&gt;\naws cloudwatch describe-alarm-history --alarm-name &lt;alarm-name&gt; --history-item-type StateUpdate</code></pre></div>","hand":false},{"id":"aws-f0152","card":"q-aws-057-scaling-load-balancer-and-database-comma","sec":"aws-s058","q":"How do you scale an Auto Scaling group to 5 instances?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws autoscaling set-desired-capacity --auto-scaling-group-name my-asg --desired-capacity 5</code></pre></div>","hand":false},{"id":"aws-f0153","card":"q-aws-057-scaling-load-balancer-and-database-comma","sec":"aws-s058","q":"How do you check ELB health and remove an unhealthy instance?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws elb describe-instance-health --load-balancer-name &lt;elb-name&gt;\naws elb deregister-instances-from-load-balancer --load-balancer-name &lt;elb-name&gt; --instances &lt;instance-id&gt;</code></pre></div>","hand":false},{"id":"aws-f0154","card":"q-aws-057-scaling-load-balancer-and-database-comma","sec":"aws-s058","q":"How do you check RDS status and reboot if it is not available?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>STATUS=$(aws rds describe-db-instances --db-instance-identifier my-rds --query &quot;DBInstances[0].DBInstanceStatus&quot; --output text); [ &quot;$STATUS&quot; != &quot;available&quot; ] &amp;&amp; aws rds reboot-db-instance --db-instance-identifier my-rds</code></pre></div>","hand":false},{"id":"aws-f0155","card":"q-aws-057-scaling-load-balancer-and-database-comma","sec":"aws-s058","q":"How do you restore RDS from a snapshot?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws rds restore-db-instance-from-db-snapshot --db-instance-identifier &lt;new-db-name&gt; --db-snapshot-identifier &lt;snapshot-id&gt;</code></pre></div>","hand":false},{"id":"aws-f0156","card":"q-aws-057-scaling-load-balancer-and-database-comma","sec":"aws-s058","q":"How do you list DynamoDB tables with their throughput?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for table in $(aws dynamodb list-tables --query &#x27;TableNames&#x27; --output text); do aws dynamodb describe-table --table-name $table --query &#x27;Table.{Name:TableName,ReadCapacity:ProvisionedThroughput.ReadCapacityUnits,WriteCapacity:ProvisionedThroughput.WriteCapacityUnits}&#x27; --output table; done</code></pre></div>","hand":false},{"id":"aws-f0157","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you download the latest CloudWatch logs for a Lambda function?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws logs get-log-events --log-group-name /aws/lambda/my-function --log-stream-name $(aws logs describe-log-streams --log-group-name /aws/lambda/my-function --order-by LastEventTime --descending --limit 1 --query &quot;logStreams[0].logStreamName&quot; --output text) --output text &gt; lambda_logs.txt</code></pre></div>","hand":false},{"id":"aws-f0158","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you invoke a Lambda function and capture the output?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws lambda invoke --function-name &lt;function-name&gt; output.json</code></pre></div>","hand":false},{"id":"aws-f0159","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you update a Lambda timeout to 10 seconds?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws lambda update-function-configuration --function-name &lt;function-name&gt; --timeout 10</code></pre></div>","hand":false},{"id":"aws-f0160","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you list running ECS tasks in a cluster?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ecs list-tasks --cluster &lt;cluster-name&gt; --desired-status RUNNING</code></pre></div>","hand":false},{"id":"aws-f0161","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you check an EKS cluster's status?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws eks describe-cluster --name &lt;cluster-name&gt; --query &#x27;cluster.status&#x27; --output text</code></pre></div>","hand":false},{"id":"aws-f0162","card":"q-aws-058-lambda-containers-and-messaging-commands","sec":"aws-s059","q":"How do you list SNS topics and their subscriptions?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for topic in $(aws sns list-topics --query &#x27;Topics[*].TopicArn&#x27; --output text); do aws sns list-subscriptions-by-topic --topic-arn $topic --query &#x27;Subscriptions[*].{Endpoint:Endpoint,Protocol:Protocol}&#x27; --output table; done</code></pre></div>","hand":false},{"id":"aws-f0163","card":"q-aws-059-blue-green-deployment-process","sec":"aws-s060","q":"How does a blue-green deployment run on AWS and EKS?","a":"<ul>\n  <li><strong>Code commit</strong>: developers push to GitHub or Bitbucket.</li>\n  <li><strong>CI/CD trigger</strong>: GitHub Actions builds and tests Docker containers.</li>\n  <li><strong>Green deployment</strong>: the new version is deployed to the Green environment (Kubernetes on EKS).</li>\n  <li><strong>Validation</strong>: test Green with CloudWatch monitoring.</li>\n  <li><strong>Traffic switch</strong>: route traffic to Green through AWS ELB or Kubernetes Ingress.</li>\n  <li><strong>Monitoring</strong>: track CPU and latency in CloudWatch.</li>\n  <li><strong>Rollback</strong>: switch back to Blue if issues arise.</li>\n</ul>","hand":false},{"id":"aws-f0164","card":"q-aws-060-delivery-metrics-affected","sec":"aws-s061","q":"Which delivery metrics does blue-green improve?","a":"<ul>\n  <li><strong>Deployment Frequency</strong>: faster through automation.</li>\n  <li><strong>Lead Time for Changes</strong>: reduced by 25%.</li>\n  <li><strong>Change Failure Rate</strong>: errors eliminated.</li>\n  <li><strong>Mean Time to Restore</strong>: minimized through rollback.</li>\n  <li><strong>Availability</strong>: preserved by the zero-downtime switch.</li>\n</ul>","hand":false},{"id":"aws-f0165","card":"q-aws-061-deployment-strategies-compared","sec":"aws-s062","q":"What deployment strategies exist and how do they compare?","a":"<ol>\n  <li><strong>Blue-Green</strong> (used): two environments (Blue is current, Green is new). Zero downtime, low MTTR, high availability. Tools: AWS ELB, Kubernetes, Terraform, CloudWatch.</li>\n  <li><strong>Canary</strong>: gradual rollout to a small user subset. Reduces change failure rate through early issue detection.</li>\n  <li><strong>Rolling</strong>: incremental pod updates in Kubernetes. Resource-efficient but risks compatibility issues.</li>\n  <li><strong>Feature flag</strong>: hide features behind toggles. Flexible, reduces change failure rate through selective rollout.</li>\n  <li><strong>A/B testing</strong>: compare versions for user feedback. Improves CSAT and NPS.</li>\n  <li><strong>Shadow</strong>: test the new version with duplicated traffic. Safe, with no user impact.</li>\n  <li><strong>Recreate</strong>: terminate the old version, deploy the new one. High risk and not used because of downtime.</li>\n</ol>","hand":false},{"id":"aws-f0166","card":"q-aws-062-comparison-with-blue-green","sec":"aws-s063","q":"How does each strategy compare with blue-green?","a":"<ul>\n  <li><strong>Canary</strong>: safer for testing, slower lead time.</li>\n  <li><strong>Rolling</strong>: resource-efficient, risks disruptions.</li>\n  <li><strong>Feature flag</strong>: ideal for feature releases.</li>\n  <li><strong>A/B</strong>: user-focused, complements data systems.</li>\n  <li><strong>Shadow</strong>: safe testing, high resource use.</li>\n  <li><strong>Recreate</strong>: unsuitable for high availability.</li>\n</ul>","hand":false},{"id":"aws-f0167","card":"q-aws-063-ec2-launch-template","sec":"aws-s064","q":"How do you build EC2 Auto Scaling with Terraform?","a":"<p>Start with a launch template.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_launch_template&quot; &quot;web_template&quot; {\n  name_prefix   = &quot;web-lt&quot;\n  image_id      = &quot;ami-0abcdef1234567890&quot;\n  instance_type = &quot;t3.micro&quot;\n  key_name      = &quot;my-key&quot;\n  network_interfaces {\n    associate_public_ip_address = true\n    security_groups             = [aws_security_group.web_sg.id]\n  }\n  user_data = base64encode(&lt;&lt;-EOF\n              #!/bin/bash\n              echo &quot;Hello from AutoScaling EC2&quot; &gt; index.html\n              nohup python3 -m http.server 80 &amp;\n              EOF\n            )\n}</code></pre></div>","hand":false},{"id":"aws-f0168","card":"q-aws-064-auto-scaling-group-and-scaling-policy","sec":"aws-s065","q":"How does the Terraform Auto Scaling group get its instances and register them with the load balancer?","a":"<p>It uses the launch template and registers instances with the ALB target group through <code>target_group_arns</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_autoscaling_group&quot; &quot;web_asg&quot; {\n  desired_capacity     = 2\n  max_size             = 4\n  min_size             = 1\n  vpc_zone_identifier  = [aws_subnet.public1.id, aws_subnet.public2.id]\n  launch_template {\n    id      = aws_launch_template.web_template.id\n    version = &quot;$Latest&quot;\n  }\n  target_group_arns = [aws_lb_target_group.web_tg.arn]\n}</code></pre></div>","hand":true},{"id":"aws-f0169","card":"q-aws-064-auto-scaling-group-and-scaling-policy","sec":"aws-s065","q":"What size does the Terraform Auto Scaling group <code>web_asg</code> start with, and what are its limits?","a":"<p>Desired capacity 2, minimum 1, maximum 4.</p>","hand":true},{"id":"aws-f0170","card":"q-aws-064-auto-scaling-group-and-scaling-policy","sec":"aws-s065","q":"How do you define a Terraform scale-out policy that adds one instance with a 300 second cooldown?","a":"<p>Use <code>aws_autoscaling_policy</code> with <code>adjustment_type = \"ChangeInCapacity\"</code> and <code>scaling_adjustment = 1</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_autoscaling_policy&quot; &quot;scale_out&quot; {\n  name                   = &quot;scale-out&quot;\n  scaling_adjustment     = 1\n  adjustment_type        = &quot;ChangeInCapacity&quot;\n  cooldown               = 300\n  autoscaling_group_name = aws_autoscaling_group.web_asg.name\n}</code></pre></div>","hand":true},{"id":"aws-f0171","card":"q-aws-065-cloudwatch-alarm-that-triggers-scaling","sec":"aws-s066","q":"How do you write a Terraform CloudWatch alarm that triggers the scale-out policy when CPU is higher than 70%?","a":"<p>Use <code>aws_cloudwatch_metric_alarm</code> with <code>GreaterThanThreshold</code>, threshold 70, and the policy ARN in <code>alarm_actions</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_cloudwatch_metric_alarm&quot; &quot;high_cpu&quot; {\n  alarm_name          = &quot;high-cpu-alarm&quot;\n  comparison_operator = &quot;GreaterThanThreshold&quot;\n  evaluation_periods  = 2\n  metric_name         = &quot;CPUUtilization&quot;\n  namespace           = &quot;AWS/EC2&quot;\n  period              = 60\n  statistic           = &quot;Average&quot;\n  threshold           = 70\n  alarm_actions       = [aws_autoscaling_policy.scale_out.arn]</code></pre></div>","hand":true},{"id":"aws-f0172","card":"q-aws-065-cloudwatch-alarm-that-triggers-scaling","sec":"aws-s066","q":"How does the Terraform CloudWatch alarm target one Auto Scaling group?","a":"<p>Through <code>dimensions</code> with <code>AutoScalingGroupName</code> set to the group's name.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>  dimensions = {\n    AutoScalingGroupName = aws_autoscaling_group.web_asg.name\n  }</code></pre></div>","hand":true},{"id":"aws-f0173","card":"q-aws-065-cloudwatch-alarm-that-triggers-scaling","sec":"aws-s066","q":"What period and evaluation periods does the Terraform <code>high_cpu</code> alarm use?","a":"<p>A period of 60 seconds and 2 evaluation periods, with the <code>Average</code> statistic.</p>","hand":true},{"id":"aws-f0174","card":"q-aws-066-alb-target-group-and-listener","sec":"aws-s067","q":"How do you define an internet-facing Application Load Balancer in Terraform?","a":"<p>Use <code>aws_lb</code> with <code>internal = false</code> and <code>load_balancer_type = \"application\"</code>, in two subnets with a security group.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb&quot; &quot;web_alb&quot; {\n  name               = &quot;web-alb&quot;\n  internal           = false\n  load_balancer_type = &quot;application&quot;\n  subnets            = [aws_subnet.public1.id, aws_subnet.public2.id]\n  security_groups    = [aws_security_group.alb_sg.id]\n}</code></pre></div>","hand":true},{"id":"aws-f0175","card":"q-aws-066-alb-target-group-and-listener","sec":"aws-s067","q":"How do you define the ALB target group in Terraform?","a":"<p>Use <code>aws_lb_target_group</code> with port 80, protocol HTTP and the VPC ID.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb_target_group&quot; &quot;web_tg&quot; {\n  name     = &quot;web-tg&quot;\n  port     = 80\n  protocol = &quot;HTTP&quot;\n  vpc_id   = aws_vpc.main.id\n}</code></pre></div>","hand":true},{"id":"aws-f0176","card":"q-aws-066-alb-target-group-and-listener","sec":"aws-s067","q":"How does a Terraform ALB listener forward traffic to the target group?","a":"<p>A listener on port 80 with a <code>default_action</code> of type <code>forward</code> to the target group ARN.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb_listener&quot; &quot;web_listener&quot; {\n  load_balancer_arn = aws_lb.web_alb.arn\n  port              = 80\n  protocol          = &quot;HTTP&quot;\n  default_action {\n    type             = &quot;forward&quot;\n    target_group_arn = aws_lb_target_group.web_tg.arn\n  }\n}</code></pre></div>","hand":true},{"id":"aws-f0177","card":"q-aws-067-alb-with-a-target-group-attachment","sec":"aws-s068","q":"How does an ALB with a target group work?","a":"<p>Attachments link instances to the target group.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb_target_group_attachment&quot; &quot;example&quot; {\n  target_group_arn = aws_lb_target_group.web_tg.arn\n  target_id        = aws_instance.example.id\n  port             = 80\n}</code></pre></div>\n<ul>\n  <li>The ALB is created in the given subnets and is internet-facing.</li>\n  <li>The target group routes traffic to EC2 instances.</li>\n  <li>Request flow: a user request hits the ALB, the ALB evaluates rules and selects a target group, the target group routes to a healthy instance, and the instance returns the response through the ALB.</li>\n  <li>Benefits: scalability (traffic spread across instances), high availability (routes only to healthy instances) and flexibility (supports various targets).</li>\n</ul>","hand":false},{"id":"aws-f0178","card":"q-aws-068-kubernetes-autoscaling-on-eks-iam-for-th","sec":"aws-s069","q":"How does Kubernetes autoscaling work on EKS with an ALB?","a":"<p>First, the ALB controller needs an IAM policy and a role that the service account can assume through the cluster's OIDC provider.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_iam_policy&quot; &quot;alb_controller&quot; {\n  name   = &quot;AWSLoadBalancerControllerIAMPolicy&quot;\n  policy = file(&quot;iam_policy_alb_controller.json&quot;)\n}\ndata &quot;aws_eks_cluster&quot; &quot;eks&quot; {\n  name = &quot;your-cluster-name&quot;\n}\ndata &quot;aws_iam_policy_document&quot; &quot;assume_role&quot; {\n  statement {\n    effect = &quot;Allow&quot;\n    principals {\n      type        = &quot;Federated&quot;\n      identifiers = [data.aws_eks_cluster.eks.identity[0].oidc.issuer]\n    }\n    actions = [&quot;sts:AssumeRoleWithWebIdentity&quot;]\n    condition {\n      test     = &quot;StringEquals&quot;\n      variable = &quot;${replace(data.aws_eks_cluster.eks.identity[0].oidc.issuer, &quot;https://&quot;, &quot;&quot;)}:sub&quot;\n      values   = [&quot;system:serviceaccount:kube-system:aws-load-balancer-controller&quot;]\n    }\n  }\n}\nresource &quot;aws_iam_role&quot; &quot;alb_sa_role&quot; {\n  name               = &quot;AmazonEKSLoadBalancerControllerRole&quot;\n  assume_role_policy = data.aws_iam_policy_document.assume_role.json\n}\nresource &quot;aws_iam_role_policy_attachment&quot; &quot;alb_attach&quot; {\n  role       = aws_iam_role.alb_sa_role.name\n  policy_arn = aws_iam_policy.alb_controller.arn\n}</code></pre></div>","hand":false},{"id":"aws-f0179","card":"q-aws-069-alb-controller-service-account-and-ingre","sec":"aws-s070","q":"How does the Kubernetes service account for the AWS Load Balancer Controller get its IAM role?","a":"<p>It carries the role ARN annotation.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: ServiceAccount\nmetadata:\n  name: aws-load-balancer-controller\n  namespace: kube-system\n  annotations:\n    eks.amazonaws.com/role-arn: arn:aws:iam::&lt;account_id&gt;:role/AmazonEKSLoadBalancerControllerRole</code></pre></div>","hand":true},{"id":"aws-f0180","card":"q-aws-069-alb-controller-service-account-and-ingre","sec":"aws-s070","q":"Which command deploys the AWS Load Balancer Controller manifest on EKS?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl apply -f v2_7_1_full.yaml</code></pre></div>","hand":true},{"id":"aws-f0181","card":"q-aws-069-alb-controller-service-account-and-ingre","sec":"aws-s070","q":"How do you define the ClusterIP service for the <code>web</code> app behind an ALB Ingress?","a":"<p>A <code>Service</code> of type <code>ClusterIP</code> selecting <code>app: web</code>, port 80 to target port 80.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kind: Service\nmetadata:\n  name: web-service\nspec:\n  type: ClusterIP\n  selector:\n    app: web\n  ports:\n    - port: 80\n      targetPort: 80</code></pre></div>","hand":true},{"id":"aws-f0182","card":"q-aws-069-alb-controller-service-account-and-ingre","sec":"aws-s070","q":"Which annotations make an EKS Ingress create an internet-facing ALB that targets pod IPs?","a":"<p><code>kubernetes.io/ingress.class: alb</code>, <code>alb.ingress.kubernetes.io/scheme: internet-facing</code> and <code>alb.ingress.kubernetes.io/target-type: ip</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>  annotations:\n    kubernetes.io/ingress.class: alb\n    alb.ingress.kubernetes.io/scheme: internet-facing\n    alb.ingress.kubernetes.io/target-type: ip</code></pre></div>","hand":true},{"id":"aws-f0183","card":"q-aws-069-alb-controller-service-account-and-ingre","sec":"aws-s070","q":"How does the <code>web-ingress</code> Ingress route requests to the service?","a":"<p>A rule with path <code>/</code> and <code>pathType: Prefix</code> sends traffic to <code>web-service</code> on port 80.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>          - path: /\n            pathType: Prefix\n            backend:\n              service:\n                name: web-service\n                port:\n                  number: 80</code></pre></div>","hand":true},{"id":"aws-f0184","card":"q-aws-070-app-deployment-and-hpa","sec":"aws-s071","q":"How does the <code>web-app</code> Deployment set CPU requests and limits on EKS?","a":"<p>It runs 2 replicas of the <code>nginx</code> image, requests <code>100m</code> CPU and limits it to <code>200m</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>        resources:\n          requests:\n            cpu: &quot;100m&quot;\n          limits:\n            cpu: &quot;200m&quot;</code></pre></div>","hand":true},{"id":"aws-f0185","card":"q-aws-070-app-deployment-and-hpa","sec":"aws-s071","q":"How do you define a HorizontalPodAutoscaler that scales <code>web-app</code> between 2 and 5 pods at 60% CPU?","a":"<p>Target the Deployment with <code>scaleTargetRef</code>, set <code>minReplicas: 2</code> and <code>maxReplicas: 5</code>, and use a CPU <code>Utilization</code> target of 60.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: autoscaling/v2\nkind: HorizontalPodAutoscaler\nmetadata:\n  name: web-hpa\nspec:\n  scaleTargetRef:\n    apiVersion: apps/v1\n    kind: Deployment\n    name: web-app\n  minReplicas: 2\n  maxReplicas: 5\n  metrics:\n  - type: Resource\n    resource:\n      name: cpu\n      target:\n        type: Utilization\n        averageUtilization: 60</code></pre></div>","hand":true},{"id":"aws-f0186","card":"q-aws-070-app-deployment-and-hpa","sec":"aws-s071","q":"Where does the Kubernetes HPA read CPU from, and how do you install it?","a":"<p>From the Metrics Server.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl apply -f https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/components.yaml</code></pre></div>","hand":true},{"id":"aws-f0187","card":"q-aws-070-app-deployment-and-hpa","sec":"aws-s071","q":"How do you scale the <code>web-app</code> Deployment by hand to 5 replicas?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl scale deployment web-app --replicas=5 -n &lt;namespace&gt;</code></pre></div>","hand":true},{"id":"aws-f0188","card":"q-aws-070-app-deployment-and-hpa","sec":"aws-s071","q":"Which component does what in EKS autoscaling with an ALB?","a":"<ul>\n  <li>The ALB routes traffic to pods through the Ingress.</li>\n  <li>The HPA scales pods on CPU through the Metrics Server.</li>\n  <li>CloudWatch alarms trigger EC2 scaling.</li>\n</ul>","hand":true},{"id":"aws-f0189","card":"q-aws-071-eks-cluster-with-one-node-group","sec":"aws-s072","q":"How do you create an EKS cluster with a single node group in Terraform?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_eks_cluster&quot; &quot;example&quot; {\n  name     = &quot;my-eks-cluster&quot;\n  role_arn = aws_iam_role.eks_role.arn\n  vpc_config {\n    subnet_ids = [aws_subnet.private1.id, aws_subnet.private2.id]\n  }\n}\nresource &quot;aws_eks_node_group&quot; &quot;example&quot; {\n  cluster_name    = aws_eks_cluster.example.name\n  node_group_name = &quot;my-node-group&quot;\n  node_role_arn   = aws_iam_role.node_role.arn\n  subnet_ids      = [aws_subnet.private1.id, aws_subnet.private2.id]\n  scaling_config {\n    desired_size = 1\n    max_size     = 2\n    min_size     = 1\n  }\n}\nresource &quot;aws_iam_role&quot; &quot;eks_role&quot; {\n  name = &quot;eks-role&quot;\n  assume_role_policy = jsonencode({\n    Version = &quot;2012-10-17&quot;\n    Statement = [{\n      Action = &quot;sts:AssumeRole&quot;\n      Effect = &quot;Allow&quot;\n      Principal = { Service = &quot;eks.amazonaws.com&quot; }\n    }]\n  })\n}\nresource &quot;aws_iam_role&quot; &quot;node_role&quot; {\n  name = &quot;eks-node-role&quot;\n  assume_role_policy = jsonencode({\n    Version = &quot;2012-10-17&quot;\n    Statement = [{\n      Action = &quot;sts:AssumeRole&quot;\n      Effect = &quot;Allow&quot;\n      Principal = { Service = &quot;ec2.amazonaws.com&quot; }\n    }]\n  })\n}</code></pre></div>","hand":false},{"id":"aws-f0190","card":"q-aws-072-vpc-peering","sec":"aws-s073","q":"How do you set up VPC peering in Terraform?","a":"<p>Create the peering connection, then add a route in each VPC to the other's CIDR.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_vpc&quot; &quot;vpc_a&quot; { cidr_block = &quot;10.0.0.0/16&quot; }\nresource &quot;aws_vpc&quot; &quot;vpc_b&quot; { cidr_block = &quot;10.1.0.0/16&quot; }\nresource &quot;aws_vpc_peering_connection&quot; &quot;peer&quot; {\n  vpc_id        = aws_vpc.vpc_a.id\n  peer_vpc_id   = aws_vpc.vpc_b.id\n  auto_accept   = true\n}\nresource &quot;aws_route&quot; &quot;vpc_a_route&quot; {\n  route_table_id            = aws_vpc.vpc_a.main_route_table_id\n  destination_cidr_block    = aws_vpc.vpc_b.cidr_block\n  vpc_peering_connection_id = aws_vpc_peering_connection.peer.id\n}\nresource &quot;aws_route&quot; &quot;vpc_b_route&quot; {\n  route_table_id            = aws_vpc.vpc_b.main_route_table_id\n  destination_cidr_block    = aws_vpc.vpc_a.cidr_block\n  vpc_peering_connection_id = aws_vpc_peering_connection.peer.id\n}</code></pre></div>","hand":false},{"id":"aws-f0191","card":"q-aws-073-s3-bucket-with-encryption-versioning-and","sec":"aws-s074","q":"How do you create a secure S3 bucket in Terraform?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_s3_bucket&quot; &quot;bucket&quot; { bucket = &quot;my-encrypted-bucket&quot; }\nresource &quot;aws_s3_bucket_server_side_encryption_configuration&quot; &quot;encryption&quot; {\n  bucket = aws_s3_bucket.bucket.bucket\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = &quot;AES256&quot;\n    }\n  }\n}\nresource &quot;aws_s3_bucket_versioning&quot; &quot;versioning&quot; {\n  bucket = aws_s3_bucket.bucket.bucket\n  versioning_configuration {\n    status = &quot;Enabled&quot;\n  }\n}\nresource &quot;aws_s3_bucket_public_access_block&quot; &quot;block&quot; {\n  bucket                  = aws_s3_bucket.bucket.bucket\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}</code></pre></div>","hand":false},{"id":"aws-f0192","card":"q-aws-074-rds-instance-with-a-security-group","sec":"aws-s075","q":"How do you create an RDS instance in Terraform?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_db_instance&quot; &quot;example&quot; {\n  allocated_storage    = 20\n  engine               = &quot;mysql&quot;\n  engine_version       = &quot;8.0.28&quot;\n  instance_class       = &quot;db.t2.micro&quot;\n  db_name              = &quot;exampledb&quot;\n  username             = &quot;exampleuser&quot;\n  password             = &quot;&lt;db-password&gt;&quot;\n  parameter_group_name = &quot;default.mysql8.0&quot;\n  skip_final_snapshot  = true\n  vpc_security_group_ids = [aws_security_group.rds.id]\n}\nresource &quot;aws_security_group&quot; &quot;rds&quot; {\n  name        = &quot;rds-sg&quot;\n  description = &quot;Security group for RDS instance&quot;\n  ingress {\n    from_port   = 3306\n    to_port     = 3306\n    protocol    = &quot;tcp&quot;\n    cidr_blocks = [&quot;0.0.0.0/0&quot;]\n  }\n}</code></pre></div>\n<p>Opening 3306 to <code>0.0.0.0/0</code> is for demonstration only. Restrict the source to the application's security group or CIDR in real use.</p>","hand":false},{"id":"aws-f0193","card":"q-aws-075-add-an-iam-policy-to-a-role","sec":"aws-s076","q":"How do you add an IAM policy to a role in Terraform?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_iam_role&quot; &quot;existing_role&quot; {\n  name = &quot;my-role&quot;\n  assume_role_policy = jsonencode({\n    Version = &quot;2012-10-17&quot;\n    Statement = [{\n      Action = &quot;sts:AssumeRole&quot;\n      Effect = &quot;Allow&quot;\n      Principal = { Service = &quot;ec2.amazonaws.com&quot; }\n    }]\n  })\n}\nresource &quot;aws_iam_policy&quot; &quot;new_policy&quot; {\n  name = &quot;new-policy&quot;\n  policy = jsonencode({\n    Version = &quot;2012-10-17&quot;\n    Statement = [{\n      Action = &quot;s3:GetObject&quot;\n      Effect = &quot;Allow&quot;\n      Resource = &quot;arn:aws:s3:::my-bucket/*&quot;\n    }]\n  })\n}\nresource &quot;aws_iam_role_policy_attachment&quot; &quot;attach&quot; {\n  role       = aws_iam_role.existing_role.name\n  policy_arn = aws_iam_policy.new_policy.arn\n}</code></pre></div>","hand":false},{"id":"aws-f0194","card":"q-aws-076-symptoms-of-imagepullbackoff-from-ecr","sec":"aws-s077","q":"A Python Flask API pod on EKS shows ImagePullBackOff when pulling from a private ECR repository. How do you troubleshoot it?","a":"<ul>\n  <li><code>kubectl get pods</code> shows <code>ImagePullBackOff</code> or <code>ErrImagePull</code>.</li>\n  <li>Logs show a failure to pull from ECR, and CloudWatch alerts fire for pod health.</li>\n</ul>\n<p>Step 1: verify the pod status.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl get pods -n &lt;namespace&gt;\nkubectl describe pod &lt;pod-name&gt; -n &lt;namespace&gt;</code></pre></div>\n<p>Typical error:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Failed to pull image &quot;&lt;aws-ecr-repo&gt;/app:latest&quot;: pull access denied, repository does not exist or may require &#x27;docker login&#x27;</code></pre></div>","hand":false},{"id":"aws-f0195","card":"q-aws-077-check-the-image-name-and-tag","sec":"aws-s078","q":"What do you confirm in the deployment when an EKS pod shows ImagePullBackOff from ECR?","a":"<p>Confirm the image reference in the deployment: <code>&lt;aws-account-id&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com/app:latest</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>    image: &lt;aws-account-id&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com/app:latest</code></pre></div>","hand":true},{"id":"aws-f0196","card":"q-aws-077-check-the-image-name-and-tag","sec":"aws-s078","q":"How do you verify that an image exists in ECR and reapply the fixed deployment?","a":"<p>Verify the image exists, correct the name or tag, and reapply.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ecr describe-images --repository-name app --region &lt;region&gt;\nkubectl apply -f &lt;deployment-file&gt;.yaml</code></pre></div>","hand":true},{"id":"aws-f0197","card":"q-aws-078-fix-registry-authentication","sec":"aws-s079","q":"What must the pod spec contain to pull from a private ECR repository?","a":"<p><code>imagePullSecrets</code> that names the ECR secret.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>spec:\n  imagePullSecrets:\n  - name: ecr-secret</code></pre></div>","hand":true},{"id":"aws-f0198","card":"q-aws-078-fix-registry-authentication","sec":"aws-s079","q":"How do you create or update the ECR pull secret in Kubernetes?","a":"<p>Use <code>aws ecr get-login-password</code> and <code>kubectl create secret docker-registry</code> with the ECR server, the username <code>AWS</code> and the password.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws ecr get-login-password --region &lt;region&gt; | kubectl create secret docker-registry ecr-secret \\\n  --docker-server=&lt;aws-account-id&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com \\\n  --docker-username=AWS \\\n  --docker-password=$(aws ecr get-login-password --region &lt;region&gt;) \\\n  --namespace &lt;namespace&gt;</code></pre></div>","hand":true},{"id":"aws-f0199","card":"q-aws-079-automate-ecr-token-refresh","sec":"aws-s080","q":"Why must you refresh the ECR pull secret in Kubernetes?","a":"<p>ECR tokens expire, so refresh the secret with a script.</p>","hand":true},{"id":"aws-f0200","card":"q-aws-079-automate-ecr-token-refresh","sec":"aws-s080","q":"How does the Python script get the ECR password for the refresh?","a":"<p>It calls <code>get_authorization_token()</code> with boto3, then base64-decodes the token and takes the part after the colon.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ecr_client = boto3.client(&#x27;ecr&#x27;, region_name=&#x27;&lt;region&gt;&#x27;)\ntoken = ecr_client.get_authorization_token()[&#x27;authorizationData&#x27;][0]\npassword = base64.b64decode(token[&#x27;authorizationToken&#x27;]).decode(&#x27;utf-8&#x27;).split(&#x27;:&#x27;)[1]</code></pre></div>","hand":true},{"id":"aws-f0201","card":"q-aws-079-automate-ecr-token-refresh","sec":"aws-s080","q":"How does the Python ECR refresh script update the Kubernetes secret?","a":"<p>It builds a <code>kubectl create secret docker-registry</code> command with <code>--dry-run=client -o yaml</code>, pipes it to <code>kubectl apply -f -</code>, and runs it with <code>subprocess.run</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>subprocess.run(cmd, shell=True, check=True)</code></pre></div>","hand":true},{"id":"aws-f0202","card":"q-aws-080-network-resource-and-ci-checks","sec":"aws-s081","q":"How do you validate network connectivity to ECR from inside an EKS cluster?","a":"<p>Run a test pod, try to reach the ECR endpoint, and check the VPC endpoints. Also check the EKS security groups.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl run -it test-pod --image=alpine --namespace &lt;namespace&gt; -- sh\nwget &lt;aws-account-id&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com\naws ec2 describe-vpc-endpoints --region &lt;region&gt;</code></pre></div>","hand":true},{"id":"aws-f0203","card":"q-aws-080-network-resource-and-ci-checks","sec":"aws-s081","q":"How do you check node resources when an EKS pod cannot start?","a":"<p>Check the nodes, and adjust pod requests and limits if needed.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl get nodes\nkubectl describe node &lt;node-name&gt;\nkubectl top nodes</code></pre></div>","hand":true},{"id":"aws-f0204","card":"q-aws-080-network-resource-and-ci-checks","sec":"aws-s081","q":"When an EKS pod fails to pull an image from ECR and you adjust its resources, which CPU and memory limits and requests does the pod spec set?","a":"<p>Limits are <code>500m</code> CPU and <code>512Mi</code> memory. Requests are <code>200m</code> CPU and <code>256Mi</code> memory.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resources:\n  limits:\n    cpu: &quot;500m&quot;\n    memory: &quot;512Mi&quot;\n  requests:\n    cpu: &quot;200m&quot;\n    memory: &quot;256Mi&quot;</code></pre></div>","hand":true},{"id":"aws-f0205","card":"q-aws-080-network-resource-and-ci-checks","sec":"aws-s081","q":"How do you reapply a deployment and watch the pod after an ImagePullBackOff fix?","a":"<p>Reapply, watch the pods, and read the logs.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl apply -f &lt;deployment-file&gt;.yaml\nkubectl get pods -n &lt;namespace&gt; -w\nkubectl logs &lt;pod-name&gt; -n &lt;namespace&gt;</code></pre></div>","hand":true},{"id":"aws-f0206","card":"q-aws-080-network-resource-and-ci-checks","sec":"aws-s081","q":"How do you prevent ImagePullBackOff from recurring?","a":"<p>Validate the image in CI.</p>","hand":true},{"id":"aws-f0207","card":"q-aws-081-eks-clusters-with-terraform","sec":"aws-s082","q":"How do you deploy a Kubernetes pod on EKS with Terraform and verify it?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;eks&quot; { source = &quot;terraform-aws-modules/eks/aws&quot;, cluster_name = &quot;my-eks&quot; }\nresource &quot;kubernetes_pod&quot; &quot;nginx&quot; {\n  metadata: { name: &quot;nginx-pod&quot; }\n  spec: { container: [{ image: &quot;nginx:latest&quot;, name: &quot;nginx&quot; }] }\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>terraform apply\naws eks update-kubeconfig --name my-eks\nkubectl get pod nginx-pod</code></pre></div>","hand":false},{"id":"aws-f0208","card":"q-aws-081-eks-clusters-with-terraform","sec":"aws-s082","q":"Terraform for EKS and a VPC, deployed through GitHub Actions?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;vpc&quot; { source = &quot;terraform-aws-modules/vpc/aws&quot; }\nmodule &quot;eks&quot; { source = &quot;terraform-aws-modules/eks/aws&quot;, subnet_ids = module.vpc.private_subnets, vpc_id = module.vpc.vpc_id }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy VPC and EKS\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: hashicorp/setup-terraform@v2\n    - run: terraform init &amp;&amp; terraform apply -auto-approve\n      env: { AWS_ACCESS_KEY_ID: ${{ secrets.AWS_ACCESS_KEY_ID }}, AWS_SECRET_ACCESS_KEY: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }</code></pre></div>","hand":false},{"id":"aws-f0209","card":"q-aws-081-eks-clusters-with-terraform","sec":"aws-s082","q":"GitHub Actions for Terraform EKS, then scale with <code>kubectl</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy EKS\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: hashicorp/setup-terraform@v2\n    - run: terraform init &amp;&amp; terraform apply -auto-approve\n    - uses: azure/setup-kubectl@v3\n    - run: |\n        aws eks update-kubeconfig --name my-eks\n        kubectl scale deployment web-app --replicas=3\n      env: { AWS_ACCESS_KEY_ID: ${{ secrets.AWS_ACCESS_KEY_ID }}, AWS_SECRET_ACCESS_KEY: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }</code></pre></div>","hand":false},{"id":"aws-f0210","card":"q-aws-081-eks-clusters-with-terraform","sec":"aws-s082","q":"Terraform for EKS, GitHub Actions to test pod scaling?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;eks&quot; { source = &quot;terraform-aws-modules/eks/aws&quot;, cluster_name = &quot;test-eks&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Test Scaling\non: push\njobs:\n  scale:\n    runs-on: ubuntu-latest\n    steps:\n    - run: |\n        aws eks update-kubeconfig --name test-eks\n        kubectl scale deployment test-app --replicas=5\n      env: { AWS_ACCESS_KEY_ID: ${{ secrets.AWS_ACCESS_KEY_ID }}, AWS_SECRET_ACCESS_KEY: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }</code></pre></div>","hand":false},{"id":"aws-f0211","card":"q-aws-082-eks-with-ansible-and-monitoring-pods","sec":"aws-s083","q":"Terraform for EKS, Ansible for a monitoring pod?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;eks&quot; { source = &quot;terraform-aws-modules/eks/aws&quot;, cluster_name = &quot;monitoring-eks&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Deploy monitor\n  hosts: localhost\n  tasks:\n  - name: Apply\n    ansible.builtin.command: kubectl apply -f monitor.yaml</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;monitor&quot; }\nspec: { containers: [{ name: &quot;prometheus&quot;, image: &quot;prom/prometheus&quot; }] }</code></pre></div>","hand":false},{"id":"aws-f0212","card":"q-aws-082-eks-with-ansible-and-monitoring-pods","sec":"aws-s083","q":"Terraform for EKS, Ansible for the Kubernetes deploy, GitHub Actions to verify?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;eks&quot; { source = &quot;terraform-aws-modules/eks/aws&quot;, cluster_name = &quot;my-eks&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Deploy K8s\n  hosts: localhost\n  tasks:\n  - name: Apply\n    ansible.builtin.command: kubectl apply -f deployment.yaml</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Verify\non: push\njobs:\n  verify:\n    runs-on: ubuntu-latest\n    steps:\n    - run: kubectl get deployment\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>","hand":false},{"id":"aws-f0213","card":"q-aws-082-eks-with-ansible-and-monitoring-pods","sec":"aws-s083","q":"Terraform for ECS, GitHub Actions for a Kubernetes alternative?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;ecs&quot; { source = &quot;terraform-aws-modules/ecs/aws&quot;, cluster_name = &quot;my-ecs&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy K8s\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - run: kubectl apply -f k8s_deployment.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>","hand":false},{"id":"aws-f0214","card":"q-aws-083-ansible-on-ec2-with-github-actions","sec":"aws-s084","q":"Ansible to install Docker on EC2, GitHub Actions to deploy a Kubernetes manifest?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Install Docker\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: docker.io, state: present }\n  - name: Start\n    ansible.builtin.service: { name: docker, state: started }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy K8s\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - run: ansible-playbook -i inventory.ini install_docker.yml\n    - uses: azure/setup-kubectl@v3\n    - run: kubectl apply -f pod.yaml</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;test-pod&quot; }\nspec: { containers: [{ name: &quot;test&quot;, image: &quot;nginx&quot; }] }</code></pre></div>","hand":false},{"id":"aws-f0215","card":"q-aws-083-ansible-on-ec2-with-github-actions","sec":"aws-s084","q":"Ansible to configure EC2, Terraform for a Kubernetes service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Configure EC2\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: curl, state: present }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;kubernetes_service&quot; &quot;web&quot; {\n  metadata: { name: &quot;web-service&quot; }\n  spec:\n    selector: { app: &quot;web&quot; }\n    port: [{ port: 80, target_port: &quot;8080&quot; }]\n    type: &quot;LoadBalancer&quot;\n}</code></pre></div>","hand":false},{"id":"aws-f0216","card":"q-aws-083-ansible-on-ec2-with-github-actions","sec":"aws-s084","q":"Ansible to update EC2, GitHub Actions to test Kubernetes?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Update EC2\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Update\n    ansible.builtin.yum: { name: &quot;*&quot;, state: latest }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Test K8s\non: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - run: kubectl get nodes\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>","hand":false},{"id":"aws-f0217","card":"q-aws-084-ingress-security-group-and-cronjob-deplo","sec":"aws-s085","q":"GitHub Actions for Ansible on EC2, then deploy a Kubernetes Ingress?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Setup EC2\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: nginx, state: present }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy Ingress\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - run: ansible-playbook -i inventory.ini setup_ec2.yml\n    - run: kubectl apply -f ingress.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata: { name: &quot;web-ingress&quot; }\nspec: { rules: [{ http: { paths: [{ path: &quot;/&quot;, pathType: &quot;Prefix&quot;, backend: { service: { name: &quot;web&quot;, port: { number: 80 } } } } ] } } ] }</code></pre></div>","hand":false},{"id":"aws-f0218","card":"q-aws-084-ingress-security-group-and-cronjob-deplo","sec":"aws-s085","q":"Ansible to update an EC2 security group, GitHub Actions to deploy a Kubernetes service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Update SG\n  hosts: localhost\n  tasks:\n  - name: Add rule\n    amazon.aws.ec2_security_group: { name: &quot;my-sg&quot;, rules: [{ proto: &quot;tcp&quot;, from_port: 80, to_port: 80, cidr_ip: &quot;0.0.0.0/0&quot; }] }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy Service\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - run: ansible-playbook update_sg.yml\n    - run: kubectl apply -f service.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>","hand":false},{"id":"aws-f0219","card":"q-aws-084-ingress-security-group-and-cronjob-deplo","sec":"aws-s085","q":"Ansible for EC2, GitHub Actions to deploy a Kubernetes CronJob?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy CronJob\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - run: kubectl apply -f cronjob.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: batch/v1\nkind: CronJob\nmetadata: { name: &quot;test-cron&quot; }\nspec:\n  schedule: &quot;*/5 * * * *&quot;\n  jobTemplate: { spec: { template: { spec: { containers: [{ name: &quot;test&quot;, image: &quot;busybox&quot;, command: [&quot;echo&quot;, &quot;Hello&quot;] }] } } } }</code></pre></div>\n<p>The Ansible step is the same <code>curl</code> install play as above.</p>","hand":false},{"id":"aws-f0220","card":"q-aws-085-building-kubernetes-on-ec2","sec":"aws-s086","q":"Ansible to configure EC2 as a Kubernetes node, GitHub Actions to verify?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Configure K8s\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: kubelet, state: present }</code></pre></div>\n<p>Verification uses the same <code>kubectl get nodes</code> workflow as above, with <code>KUBECONFIG</code> from secrets.</p>","hand":false},{"id":"aws-f0221","card":"q-aws-085-building-kubernetes-on-ec2","sec":"aws-s086","q":"Terraform for ASG, Ansible for a Kubernetes agent?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;asg&quot; {\n  source = &quot;terraform-aws-modules/autoscaling/aws&quot;\n  name = &quot;my-asg&quot;\n  min_size = 1\n  max_size = 3\n  vpc_zone_identifier = [&quot;subnet-1&quot;]\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Install K8s agent\n  hosts: asg_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: kubeadm, state: present }</code></pre></div>","hand":false},{"id":"aws-f0222","card":"q-aws-085-building-kubernetes-on-ec2","sec":"aws-s086","q":"Terraform for EC2, Ansible to join the node to a Kubernetes cluster?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_instance&quot; &quot;k8s_node&quot; { ami = &quot;ami-0c55b159cbfafe1f0&quot;, instance_type = &quot;t2.medium&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Join K8s\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: kubeadm, state: present }\n  - name: Join\n    ansible.builtin.command: kubeadm join &lt;master-ip&gt;:6443 --token &lt;token&gt; --discovery-token-ca-cert-hash &lt;hash&gt;</code></pre></div>","hand":false},{"id":"aws-f0223","card":"q-aws-085-building-kubernetes-on-ec2","sec":"aws-s086","q":"Ansible to build a Kubernetes cluster on EC2, GitHub Actions to verify?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Install K8s\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.package: { name: &quot;{{ item }}&quot;, state: present }\n    loop: [kubeadm, kubelet, kubectl]\n  - name: Init master\n    ansible.builtin.command: kubeadm init --pod-network-cidr=10.244.0.0/16\n    when: inventory_hostname == &quot;master&quot;</code></pre></div>","hand":false},{"id":"aws-f0224","card":"q-aws-085-building-kubernetes-on-ec2","sec":"aws-s086","q":"Ansible to install <code>kubectl</code> on EC2, GitHub Actions to deploy a pod?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Install kubectl\n  hosts: ec2_hosts\n  become: yes\n  tasks:\n  - name: Install\n    ansible.builtin.shell: |\n      curl -LO &quot;https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl&quot;\n      chmod +x kubectl &amp;&amp; mv kubectl /usr/local/bin/</code></pre></div>\n<p>The deploy step is <code>kubectl apply -f pod.yaml</code> with <code>KUBECONFIG</code> from secrets, as in the other workflows.</p>","hand":false},{"id":"aws-f0225","card":"q-aws-086-s3-cloudfront-and-lambda-with-github-act","sec":"aws-s087","q":"Terraform for an S3 bucket, GitHub Actions to upload files?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_s3_bucket&quot; &quot;my_bucket&quot; { bucket = &quot;my-unique-bucket-123&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Upload S3\non: push\njobs:\n  upload:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - uses: aws-actions/configure-aws-credentials@v2\n      with: { aws-access-key-id: ${{ secrets.AWS_ACCESS_KEY_ID }}, aws-secret-access-key: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }\n    - run: aws s3 cp file.txt s3://my-unique-bucket-123/</code></pre></div>","hand":false},{"id":"aws-f0226","card":"q-aws-086-s3-cloudfront-and-lambda-with-github-act","sec":"aws-s087","q":"Terraform for CloudFront, GitHub Actions to sync assets?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_cloudfront_distribution&quot; &quot;cdn&quot; {\n  origin: { domain_name: &quot;my-bucket.s3.amazonaws.com&quot;, origin_id: &quot;S3-my-bucket&quot; }\n  enabled: true\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Sync CloudFront\non: push\njobs:\n  sync:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: aws-actions/configure-aws-credentials@v2\n      with: { aws-access-key-id: ${{ secrets.AWS_ACCESS_KEY_ID }}, aws-secret-access-key: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }\n    - run: aws s3 sync ./assets s3://my-bucket/</code></pre></div>","hand":false},{"id":"aws-f0227","card":"q-aws-086-s3-cloudfront-and-lambda-with-github-act","sec":"aws-s087","q":"GitHub Actions to deploy AWS Lambda, and a Kubernetes pod to monitor it?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy Lambda\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v3\n    - uses: aws-actions/configure-aws-credentials@v2\n      with: { aws-access-key-id: ${{ secrets.AWS_ACCESS_KEY_ID }}, aws-secret-access-key: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }\n    - run: zip -r lambda.zip . &amp;&amp; aws lambda update-function-code --function-name my-lambda --zip-file fileb://lambda.zip</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;lambda-monitor&quot; }\nspec: { containers: [{ name: &quot;monitor&quot;, image: &quot;amazon/aws-cli&quot;, command: [&quot;aws&quot;, &quot;lambda&quot;, &quot;get-function&quot;, &quot;--function-name&quot;, &quot;my-lambda&quot;] }] }</code></pre></div>","hand":false},{"id":"aws-f0228","card":"q-aws-086-s3-cloudfront-and-lambda-with-github-act","sec":"aws-s087","q":"GitHub Actions to deploy Lambda, a Kubernetes pod to log invocations?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- run: aws lambda update-function-code --function-name my-lambda --zip-file fileb://lambda.zip\n- run: kubectl apply -f logger.yaml\n  env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;lambda-logger&quot; }\nspec: { containers: [{ name: &quot;logger&quot;, image: &quot;amazon/aws-cli&quot;, command: [&quot;aws&quot;, &quot;logs&quot;, &quot;filter-log-events&quot;, &quot;--log-group-name&quot;, &quot;/aws/lambda/my-lambda&quot;] }] }</code></pre></div>","hand":false},{"id":"aws-f0229","card":"q-aws-086-s3-cloudfront-and-lambda-with-github-act","sec":"aws-s087","q":"Terraform for a Lambda timeout fix, GitHub Actions to trigger a Kubernetes job?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lambda_function&quot; &quot;fix&quot; { function_name = &quot;my-lambda&quot;, timeout = 60, filename = &quot;lambda.zip&quot;, handler = &quot;index.handler&quot;, runtime = &quot;nodejs16.x&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: batch/v1\nkind: Job\nmetadata: { name: &quot;lambda-check&quot; }\nspec:\n  template:\n    spec:\n      containers:\n      - name: check\n        image: amazon/aws-cli\n        command: [&quot;aws&quot;, &quot;lambda&quot;, &quot;get-function&quot;, &quot;--function-name&quot;, &quot;my-lambda&quot;]</code></pre></div>\n<p>The trigger workflow runs <code>kubectl apply -f job.yaml</code> with <code>KUBECONFIG</code> from secrets.</p>","hand":false},{"id":"aws-f0230","card":"q-aws-087-rds-alb-and-vpc-with-github-actions","sec":"aws-s088","q":"GitHub Actions for Terraform RDS, connect a Kubernetes app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_db_instance&quot; &quot;db&quot; { identifier = &quot;my-rds&quot;, engine = &quot;mysql&quot;, instance_class = &quot;db.t3.micro&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy RDS\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: hashicorp/setup-terraform@v2\n    - run: terraform init &amp;&amp; terraform apply -auto-approve\n    - run: kubectl apply -f app.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;app&quot; }\nspec: { containers: [{ name: &quot;app&quot;, image: &quot;mysql:5.7&quot;, env: [{ name: &quot;MYSQL_HOST&quot;, value: &quot;my-rds.endpoint&quot; }] }] }</code></pre></div>","hand":false},{"id":"aws-f0231","card":"q-aws-087-rds-alb-and-vpc-with-github-actions","sec":"aws-s088","q":"GitHub Actions for a Terraform ALB, Kubernetes Ingress?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb&quot; &quot;app_lb&quot; { name = &quot;app-lb&quot;, load_balancer_type = &quot;application&quot;, subnets = [&quot;subnet-1&quot;, &quot;subnet-2&quot;] }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Deploy ALB\non: push\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: hashicorp/setup-terraform@v2\n    - run: terraform init &amp;&amp; terraform apply -auto-approve\n    - run: kubectl apply -f ingress.yaml\n      env: { KUBECONFIG: ${{ secrets.KUBECONFIG }} }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata: { name: &quot;app-ingress&quot; }\nspec: { rules: [{ http: { paths: [{ path: &quot;/&quot;, pathType: &quot;Prefix&quot;, backend: { service: { name: &quot;app&quot;, port: { number: 80 } } } } ] } } ] }</code></pre></div>","hand":false},{"id":"aws-f0232","card":"q-aws-087-rds-alb-and-vpc-with-github-actions","sec":"aws-s088","q":"Terraform for an ALB, expose a Kubernetes service with <code>kubectl</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb&quot; &quot;my_alb&quot; { name = &quot;my-alb&quot;, load_balancer_type = &quot;application&quot;, subnets = [&quot;subnet-1&quot;, &quot;subnet-2&quot;] }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl expose service web-service --type=LoadBalancer --name=web-lb --port=80\nkubectl annotate service web-lb &quot;service.beta.kubernetes.io/aws-load-balancer-arn=arn:aws:elasticloadbalancing:us-east-1:123:loadbalancer/app/my-alb/abc123&quot;</code></pre></div>","hand":false},{"id":"aws-f0233","card":"q-aws-087-rds-alb-and-vpc-with-github-actions","sec":"aws-s088","q":"Terraform for a VPC, Ansible for Kubernetes networking?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>module &quot;vpc&quot; { source = &quot;terraform-aws-modules/vpc/aws&quot;, vpc_name = &quot;k8s-vpc&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Setup networking\n  hosts: localhost\n  tasks:\n  - name: Apply\n    ansible.builtin.command: kubectl apply -f https://raw.githubusercontent.com/coreos/flannel/master/Documentation/kube-flannel.yml</code></pre></div>","hand":false},{"id":"aws-f0234","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for SQS, a Kubernetes pod to process it, deployed with Ansible?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_sqs_queue&quot; &quot;my_queue&quot; { name = &quot;my-queue&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;sqs-processor&quot; }\nspec: { containers: [{ name: &quot;processor&quot;, image: &quot;amazon/aws-cli&quot;, command: [&quot;aws&quot;, &quot;sqs&quot;, &quot;receive-message&quot;, &quot;--queue-url&quot;, &quot;&lt;queue-url&gt;&quot;] }] }</code></pre></div>\n<p>The Ansible play runs <code>kubectl apply -f processor.yaml</code> on localhost.</p>","hand":false},{"id":"aws-f0235","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for DynamoDB, Ansible to populate it from a Kubernetes pod?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_dynamodb_table&quot; &quot;my_table&quot; { name = &quot;my-table&quot;, billing_mode = &quot;PAY_PER_REQUEST&quot;, hash_key = &quot;id&quot;, attribute: [{ name: &quot;id&quot;, type: &quot;S&quot; }] }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;dynamo-populator&quot; }\nspec: { containers: [{ name: &quot;populator&quot;, image: &quot;amazon/aws-cli&quot;, command: [&quot;aws&quot;, &quot;dynamodb&quot;, &quot;put-item&quot;, &quot;--table-name&quot;, &quot;my-table&quot;, &quot;--item&quot;, &quot;{\\&quot;id\\&quot;: {\\&quot;S\\&quot;: \\&quot;1\\&quot;}, \\&quot;data\\&quot;: {\\&quot;S\\&quot;: \\&quot;test\\&quot;}}&quot;] }] }</code></pre></div>\n<p>The Ansible play runs <code>kubectl apply -f populator.yaml</code> on localhost.</p>","hand":false},{"id":"aws-f0236","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for S3 and a ConfigMap, Ansible to sync them?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_s3_bucket&quot; &quot;config&quot; { bucket = &quot;config-bucket-123&quot; }\nresource &quot;kubernetes_configmap&quot; &quot;app&quot; {\n  metadata: { name: &quot;app-config&quot; }\n  data: { key: &quot;value&quot; }\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- name: Sync ConfigMap\n  hosts: localhost\n  tasks:\n  - name: Export\n    ansible.builtin.command: kubectl get configmap app-config -o yaml &gt; config.yaml\n  - name: Upload\n    amazon.aws.aws_s3: { bucket: config-bucket-123, src: config.yaml, dest: config.yaml, mode: put }</code></pre></div>","hand":false},{"id":"aws-f0237","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for a CloudWatch alarm, Ansible to alert from a Kubernetes pod?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_cloudwatch_metric_alarm&quot; &quot;cpu&quot; {\n  alarm_name = &quot;high-cpu&quot;\n  comparison_operator = &quot;GreaterThanThreshold&quot;\n  threshold = &quot;80&quot;\n  metric_name = &quot;CPUUtilization&quot;\n  namespace = &quot;AWS/EC2&quot;\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: Pod\nmetadata: { name: &quot;alert-pod&quot; }\nspec: { containers: [{ name: &quot;alert&quot;, image: &quot;busybox&quot;, command: [&quot;sh&quot;, &quot;-c&quot;, &quot;echo Alarm &amp;&amp; sleep 3600&quot;] }] }</code></pre></div>\n<p>The Ansible play runs <code>kubectl apply -f alert.yaml</code> on localhost.</p>","hand":false},{"id":"aws-f0238","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for SNS, GitHub Actions to notify on pod failure?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_sns_topic&quot; &quot;alerts&quot; { name = &quot;pod-failure-alerts&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>name: Notify Failure\non: workflow_run\njobs:\n  notify:\n    if: failure()\n    runs-on: ubuntu-latest\n    steps:\n    - uses: aws-actions/configure-aws-credentials@v2\n      with: { aws-access-key-id: ${{ secrets.AWS_ACCESS_KEY_ID }}, aws-secret-access-key: ${{ secrets.AWS_SECRET_ACCESS_KEY }} }\n    - run: aws sns publish --topic-arn ${{ secrets.SNS_TOPIC_ARN }} --message &quot;Pod failed&quot;</code></pre></div>","hand":false},{"id":"aws-f0239","card":"q-aws-088-messaging-data-and-alerting-integrations","sec":"aws-s089","q":"Terraform for EBS, Ansible to attach it to a Kubernetes pod?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_ebs_volume&quot; &quot;data&quot; { availability_zone = &quot;us-east-1a&quot;, size = 10 }\nresource &quot;aws_volume_attachment&quot; &quot;attach&quot; { device_name = &quot;/dev/xvdf&quot;, volume_id = aws_ebs_volume.data.id, instance_id = &quot;i-123&quot; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>apiVersion: v1\nkind: PersistentVolumeClaim\nmetadata: { name: &quot;data-pvc&quot; }\nspec: { accessModes: [&quot;ReadWriteOnce&quot;], resources: { requests: { storage: &quot;10Gi&quot; } } }</code></pre></div>\n<p>The Ansible play runs <code>kubectl apply -f pvc.yaml</code> on localhost.</p>","hand":false},{"id":"aws-f0240","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot a Kubernetes pod on EKS and update the AWS security group with Terraform?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl get pod &lt;pod-name&gt;\nkubectl describe pod &lt;pod-name&gt;\nkubectl logs &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_security_group_rule&quot; &quot;allow_pod&quot; {\n  type = &quot;ingress&quot;\n  from_port = 80\n  to_port = 80\n  protocol = &quot;tcp&quot;\n  cidr_blocks = [&quot;0.0.0.0/0&quot;]\n  security_group_id = &quot;sg-123&quot;\n}</code></pre></div>","hand":false},{"id":"aws-f0241","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot an RDS connection from a Kubernetes pod, with a Terraform fix?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl exec -it &lt;pod-name&gt; -- ping &lt;rds-endpoint&gt;\nkubectl describe pod &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_security_group_rule&quot; &quot;rds_access&quot; {\n  type = &quot;ingress&quot;\n  from_port = 3306\n  to_port = 3306\n  protocol = &quot;tcp&quot;\n  source_security_group_id = &quot;sg-pod&quot;\n  security_group_id = &quot;sg-rds&quot;\n}</code></pre></div>","hand":false},{"id":"aws-f0242","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot a pod failing to pull from ECR, with a Terraform fix?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl describe pod &lt;pod-name&gt;\naws ecr get-login-password | docker login --username AWS --password-stdin &lt;ecr-repo&gt;\nkubectl create secret docker-registry ecr-secret --docker-server=&lt;ecr-repo&gt; --docker-username=AWS --docker-password=&lt;password&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;kubernetes_pod&quot; &quot;fix&quot; { spec: { image_pull_secrets: [{ name: &quot;ecr-secret&quot; }] } }</code></pre></div>","hand":false},{"id":"aws-f0243","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot pod networking on EKS, with a Terraform VPC fix?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl exec -it &lt;pod-name&gt; -- ping 8.8.8.8\nkubectl describe pod &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_vpc&quot; &quot;eks_vpc&quot; { cidr_block = &quot;10.0.0.0/16&quot;, enable_dns_hostnames = true }\nresource &quot;aws_route&quot; &quot;internet&quot; { route_table_id = &quot;rt-123&quot;, destination_cidr_block = &quot;0.0.0.0/0&quot;, gateway_id = &quot;igw-123&quot; }</code></pre></div>","hand":false},{"id":"aws-f0244","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot an AWS ELB that is not routing to Kubernetes pods?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl get svc &lt;service-name&gt; -o wide\nkubectl describe pod &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_lb_target_group_attachment&quot; &quot;fix&quot; { target_group_arn = &quot;arn:aws:elasticloadbalancing:us-east-1:123:targetgroup/my-tg/abc&quot;, target_id = &quot;i-123&quot; }</code></pre></div>","hand":false},{"id":"aws-f0245","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot S3 access from a Kubernetes pod, with a Terraform IAM fix?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl exec -it &lt;pod-name&gt; -- aws s3 ls s3://my-bucket\nkubectl describe pod &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_iam_role_policy&quot; &quot;s3_access&quot; {\n  role = &quot;eks-node-role&quot;\n  policy = jsonencode({ Statement: [{ Effect: &quot;Allow&quot;, Action: &quot;s3:*&quot;, Resource: &quot;arn:aws:s3:::my-bucket/*&quot; }] })\n}</code></pre></div>","hand":false},{"id":"aws-f0246","card":"q-aws-089-troubleshooting-pods-against-aws-service","sec":"aws-s090","q":"How do you troubleshoot a Kubernetes pod crash on EKS, with a Terraform resource fix?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>kubectl logs &lt;pod-name&gt;\nkubectl describe pod &lt;pod-name&gt;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Hcl</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>resource &quot;aws_eks_node_group&quot; &quot;fix&quot; {\n  cluster_name = &quot;my-eks&quot;\n  node_group_name = &quot;fixed-nodes&quot;\n  scaling_config: { desired_size: 2, max_size: 3, min_size: 1 }\n  instance_types: [&quot;t3.large&quot;]\n}</code></pre></div>","hand":false},{"id":"aws-f0247","card":"q-aws-090-ansible-vs-terraform-on-aws","sec":"aws-s091","q":"What are the key differences between Ansible and Terraform when managing AWS resources?","a":"<ul>\n  <li><strong>Approach</strong>: Terraform is declarative (defines desired state). Ansible is procedural (defines steps to reach a state).</li>\n  <li><strong>Focus</strong>: Terraform provisions infrastructure (for example EC2 instances). Ansible configures it (for example installing software on instances).</li>\n  <li><strong>State</strong>: Terraform keeps a state file. Ansible is stateless.</li>\n  <li><strong>Python integration</strong>: Terraform through <code>python-terraform</code> or <code>subprocess</code>. Ansible through the <code>ansible</code> Python API or custom modules.</li>\n</ul>","hand":false},{"id":"aws-f0248","card":"q-aws-091-securing-aws-credentials","sec":"aws-s092","q":"How do you keep AWS credentials secure in Python scripts?","a":"<ul>\n  <li><strong>IAM roles</strong>: assign roles to EC2 instances or Lambda functions so no credentials are hardcoded.</li>\n  <li><strong>AWS Secrets Manager</strong>: store credentials there and retrieve them with boto3.</li>\n  <li><strong>Environment variables or CLI profiles</strong>: <code>AWS_ACCESS_KEY_ID</code> and <code>AWS_SECRET_ACCESS_KEY</code> in the environment, or named profiles in <code>~/.aws/credentials</code>.</li>\n  <li><strong>No hardcoding</strong>: never embed credentials in source code.</li>\n  <li><strong>Least privilege</strong>: give roles and users minimal permissions.</li>\n</ul>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import boto3\nclient = boto3.client(&#x27;secretsmanager&#x27;)\nsecret = client.get_secret_value(SecretId=&#x27;my-secret&#x27;)[&#x27;SecretString&#x27;]</code></pre></div>","hand":false},{"id":"aws-f0249","card":"q-aws-092-api-rate-limits","sec":"aws-s093","q":"How do you handle AWS API rate limits in scripts?","a":"<ul>\n  <li>Use boto3's built-in retry mechanism, or <code>tenacity</code> for custom retries.</li>\n  <li>Apply exponential backoff for transient errors.</li>\n  <li>Check AWS service quotas and adjust the script logic.</li>\n</ul>","hand":false},{"id":"aws-f0250","card":"q-aws-093-challenges-of-multi-cloud-automation","sec":"aws-s094","q":"What are the challenges of managing multi-cloud resources (for example AWS and Kubernetes) from scripts?","a":"<ul>\n  <li><strong>Complexity</strong>: each API has its own nuances.</li>\n  <li><strong>Authentication</strong>: different mechanisms (AWS IAM vs. Kubernetes RBAC).</li>\n  <li><strong>State</strong>: reconciling Terraform state with Kubernetes resources.</li>\n  <li><strong>Error handling</strong>: varied error formats and retry policies.</li>\n  <li><strong>Dependencies</strong>: library versions and compatibility.</li>\n</ul>","hand":false},{"id":"aws-f0251","card":"q-aws-094-idempotency-across-tools","sec":"aws-s095","q":"How do you ensure idempotency across tools?","a":"<ul>\n  <li><strong>Terraform</strong>: state files ensure resources are created or updated only when needed.</li>\n  <li><strong>Ansible</strong>: use <code>state</code> parameters (for example <code>state=present</code>) and check conditions.</li>\n  <li><strong>boto3</strong>: check that a resource exists before creating it (for example <code>head_bucket</code> for S3).</li>\n  <li><strong>Kubernetes</strong>: use <code>apply</code> semantics to reconcile desired and actual state.</li>\n  <li><strong>GitHub Actions</strong>: use conditional steps to avoid redundant actions.</li>\n</ul>","hand":false}];
